values ('t11', 11, 'Mock Test #11', 8, 2026, false, true, false, $json${"sections":[{"kind":"listening","title":"Listening","parts":6,"questions":35,"minutes":35},{"kind":"reading","title":"Reading","parts":5,"questions":35,"minutes":60},{"kind":"writing","title":"Writing","parts":2,"minutes":60},{"kind":"speaking","title":"Speaking","parts":3,"minutes":15,"approx":true}],"listening":[{"id":"l1","index":1,"instruction":"You will hear some sentences. Choose the correct reply to each sentence.","emphasis":"A, B or C","durationSec":50,"questions":[{"id":"l-1","number":1,"kind":"mcq","prompt":"","options":[{"key":"A","text":"No, please sit down."},{"key":"B","text":"Yes, I sit here every day."},{"key":"C","text":"It was very comfortable."}]},{"id":"l-2","number":2,"kind":"mcq","prompt":"","options":[{"key":"A","text":"It left yesterday."},{"key":"B","text":"In about ten minutes."},{"key":"C","text":"By bus, usually."}]},{"id":"l-3","number":3,"kind":"mcq","prompt":"","options":[{"key":"A","text":"Never mind, we haven't started yet."},{"key":"B","text":"Yes, I'm late too."},{"key":"C","text":"I'll take a taxi."}]},{"id":"l-4","number":4,"kind":"mcq","prompt":"","options":[{"key":"A","text":"They're quite heavy."},{"key":"B","text":"Upstairs, on the left."},{"key":"C","text":"Of course, give me one."}]},{"id":"l-5","number":5,"kind":"mcq","prompt":"","options":[{"key":"A","text":"Yes, please."},{"key":"B","text":"Coffee, please, with milk."},{"key":"C","text":"I like it very much."}]},{"id":"l-6","number":6,"kind":"mcq","prompt":"","options":[{"key":"A","text":"That's fantastic news!"},{"key":"B","text":"Which one would you offer?"},{"key":"C","text":"I'm sorry to hear that."}]},{"id":"l-7","number":7,"kind":"mcq","prompt":"","options":[{"key":"A","text":"Yes, it's a blue one."},{"key":"B","text":"Not at all, here you are."},{"key":"C","text":"I've borrowed it already."}]},{"id":"l-8","number":8,"kind":"mcq","prompt":"","options":[{"key":"A","text":"I'm going next week."},{"key":"B","text":"By train, it was quicker."},{"key":"C","text":"Wonderful, the old town was amazing."}]}],"audio":"t11/l1.mp3","audioAt":{"1":8,"2":12,"3":17,"4":25,"5":29,"6":33,"7":38,"8":43}},{"id":"l2","index":2,"title":"Central Library — tour notes","instruction":"You will hear a librarian giving a tour. Fill in the missing information. Write","emphasis":"ONE WORD and / or A NUMBER","durationSec":76,"questions":[{"id":"l-9","number":9,"kind":"gap","prompt":"Members can borrow up to … books at a time"},{"id":"l-10","number":10,"kind":"gap","prompt":"Study rooms are on the … floor"},{"id":"l-11","number":11,"kind":"gap","prompt":"To use a printer, get a code from the"},{"id":"l-12","number":12,"kind":"gap","prompt":"Fine for late books: … som per day"},{"id":"l-13","number":13,"kind":"gap","prompt":"In the quiet zone, no … is allowed"},{"id":"l-14","number":14,"kind":"gap","prompt":"The library is closed every"}],"audio":"t11/l2.mp3","audioAt":{"9":18,"10":27,"11":37,"12":46,"13":54,"14":63}},{"id":"l3","index":3,"instruction":"You will hear people speaking in different situations. Match each speaker (15–18) to the place where the speaker is (A–F). There are","emphasis":"TWO EXTRA places","durationSec":73,"choices":[{"key":"A","text":"at an airport"},{"key":"B","text":"in a bank"},{"key":"C","text":"at a cinema"},{"key":"D","text":"at a doctor's"},{"key":"E","text":"in a restaurant"},{"key":"F","text":"at a zoo"}],"questions":[{"id":"l-15","number":15,"kind":"match","prompt":"Speaker 1"},{"id":"l-16","number":16,"kind":"match","prompt":"Speaker 2"},{"id":"l-17","number":17,"kind":"match","prompt":"Speaker 3"},{"id":"l-18","number":18,"kind":"match","prompt":"Speaker 4"}],"audio":"t11/l3.mp3","audioAt":{"15":14,"16":30,"17":42,"18":55}},{"id":"l4","index":4,"instruction":"You will hear someone giving a talk. Label the places (19–23) on the map (A–H). There are","emphasis":"THREE extra options","durationSec":77,"choices":[{"key":"A","text":""},{"key":"B","text":""},{"key":"C","text":""},{"key":"D","text":""},{"key":"E","text":""},{"key":"F","text":""},{"key":"G","text":""},{"key":"H","text":""}],"map":{"width":320,"height":240,"roads":[{"points":[[10,112],[310,112]]},{"points":[[110,112],[110,230]]},{"points":[[230,10],[230,112]]}],"blocks":[{"x":20,"y":62,"w":55,"h":34,"letter":"A"},{"x":92,"y":62,"w":55,"h":34,"letter":"B"},{"x":162,"y":62,"w":55,"h":34,"letter":"C"},{"x":246,"y":28,"w":55,"h":34,"letter":"D"},{"x":246,"y":128,"w":55,"h":34,"letter":"E"},{"x":20,"y":128,"w":70,"h":34,"letter":"F"},{"x":148,"y":128,"w":64,"h":30,"name":"Main entrance"},{"x":126,"y":184,"w":55,"h":34,"letter":"G"},{"x":36,"y":186,"w":55,"h":34,"letter":"H"}],"labels":[{"x":60,"y":116,"text":"Campus Road"},{"x":110,"y":236,"text":"Library Walk"},{"x":230,"y":20,"text":"Park Lane"}]},"questions":[{"id":"l-19","number":19,"kind":"match","prompt":"Canteen"},{"id":"l-20","number":20,"kind":"match","prompt":"Sports field"},{"id":"l-21","number":21,"kind":"match","prompt":"Science building"},{"id":"l-22","number":22,"kind":"match","prompt":"Bookshop"},{"id":"l-23","number":23,"kind":"match","prompt":"Student office"}],"audio":"t11/l4.mp3","audioAt":{"19":23,"20":33,"21":44,"22":56,"23":62}},{"id":"l5","index":5,"instruction":"You will hear three extracts. Choose the correct answer (A, B or C) for each question. There are","emphasis":"TWO questions for each extract","durationSec":102,"questions":[{"id":"l-24","number":24,"kind":"mcq","prompt":"Where are the friends going to camp?","options":[{"key":"A","text":"by a lake"},{"key":"B","text":"in the mountains"},{"key":"C","text":"near the sea"}],"group":"Extract One"},{"id":"l-25","number":25,"kind":"mcq","prompt":"What does Zarina still need to buy?","options":[{"key":"A","text":"a tent"},{"key":"B","text":"a sleeping bag"},{"key":"C","text":"a torch"}],"group":"Extract One"},{"id":"l-26","number":26,"kind":"mcq","prompt":"What gave Malika the idea for her app?","options":[{"key":"A","text":"her grandmother's problem with remembering medicine"},{"key":"B","text":"a project at school"},{"key":"C","text":"a national competition"}],"group":"Extract Two"},{"id":"l-27","number":27,"kind":"mcq","prompt":"What does Malika find most difficult now?","options":[{"key":"A","text":"learning new programming languages"},{"key":"B","text":"finding investors"},{"key":"C","text":"balancing her studies and her work"}],"group":"Extract Two"},{"id":"l-28","number":28,"kind":"mcq","prompt":"What is the man complaining about?","options":[{"key":"A","text":"loud music"},{"key":"B","text":"a barking dog"},{"key":"C","text":"building work"}],"group":"Extract Three"},{"id":"l-29","number":29,"kind":"mcq","prompt":"What do the neighbours decide to do?","options":[{"key":"A","text":"call the police"},{"key":"B","text":"talk to the owner together"},{"key":"C","text":"write to the newspaper"}],"group":"Extract Three"}],"audio":"t11/l5.mp3","audioAt":{"24":21,"25":30,"26":49,"27":61,"28":78,"29":89}},{"id":"l6","index":6,"title":"The history of paper","instruction":"You will hear a part of a lecture. Fill in the missing information. Write","emphasis":"no more than ONE WORD","durationSec":67,"questions":[{"id":"l-30","number":30,"kind":"gap","prompt":"Before paper, people in China wrote on bamboo and"},{"id":"l-31","number":31,"kind":"gap","prompt":"Early paper was made from tree bark, old cloth and fishing"},{"id":"l-32","number":32,"kind":"gap","prompt":"Paper-making reached Samarkand through Chinese"},{"id":"l-33","number":33,"kind":"gap","prompt":"Samarkand paper was famous for being smooth and"},{"id":"l-34","number":34,"kind":"gap","prompt":"In Europe, paper slowly replaced"},{"id":"l-35","number":35,"kind":"gap","prompt":"Most paper today is made from"}],"audio":"t11/l6.mp3","audioAt":{"30":16,"31":23,"32":32,"33":41,"34":50,"35":57}}],"reading":[{"id":"r1","index":1,"title":"Learning a language as an adult","instruction":"Read the text. Fill in each gap with ONE word. You must use a word which is somewhere in the rest of the text.","passage":[{"label":"1","text":"Many people believe that only children can learn a new language well. However, research shows that (1) ______ can also become excellent speakers. In fact, adults often learn grammar faster than children, because they can use their knowledge of their first (2) ______."},{"label":"2","text":"The biggest problem for adult learners is usually time. Busy people with jobs and families find it hard to (3) ______ every day. Experts say that short, regular practice is better than one long lesson a week. Even ten minutes a day can make a big (4) ______."},{"label":"3","text":"Another important thing is not to be afraid of making (5) ______. Children make mistakes all the time and do not worry about them. Finally, it helps to find a (6) ______ — someone who speaks the language and wants to learn yours. Adults who practise with a partner often stay motivated for longer, and every small difference in your daily routine helps. So try to practise little and often."}],"questions":[{"id":"r-1","number":1,"kind":"gap","prompt":"Research shows that (1) ______ can also become excellent speakers."},{"id":"r-2","number":2,"kind":"gap","prompt":"They can use their knowledge of their first (2) ______."},{"id":"r-3","number":3,"kind":"gap","prompt":"Busy people find it hard to (3) ______ every day."},{"id":"r-4","number":4,"kind":"gap","prompt":"Even ten minutes a day can make a big (4) ______."},{"id":"r-5","number":5,"kind":"gap","prompt":"Do not be afraid of making (5) ______."},{"id":"r-6","number":6,"kind":"gap","prompt":"It helps to find a (6) ______."}]},{"id":"r2","index":2,"title":"Online courses","instruction":"Read the texts 7–14 and the statements A–J. Decide which text matches the situation in each statement. Each statement can be used ONCE only. There are TWO extra statements.","passage":[{"label":"7","text":"CODE STARTER — Learn programming from zero. Live lessons with a teacher every evening at 7 pm. Certificate at the end of the course."},{"label":"8","text":"SPEAK UP ENGLISH — Conversation practice with native speakers in groups of four. Your first lesson is free, so you can see if it is right for you."},{"label":"9","text":"PHOTO MASTER — Recorded video lessons that you can watch whenever you want. Pay once and keep access for life."},{"label":"10","text":"KIDS SCIENCE LAB — Fun experiments for children aged 8–12. Parents receive a short report on their progress every week."},{"label":"11","text":"BUSINESS ACCOUNTING — Our course prepares you for the official professional examination. Last year, 92% of our students passed."},{"label":"12","text":"BALCONY GARDENING — A six-week course on growing vegetables in small spaces. A box of seeds and tools is posted to your home."},{"label":"13","text":"CAREER COACH — One-to-one online sessions with an experienced adviser who will help you write your CV and prepare for job interviews."},{"label":"14","text":"CHESS ACADEMY — Online tournaments every weekend. The best players win a place at the national championship."}],"choices":[{"key":"A","text":"You would like to receive materials by post."},{"key":"B","text":"You want individual help to find a job."},{"key":"C","text":"You want to try a lesson before paying."},{"key":"D","text":"You want to learn how to cook."},{"key":"E","text":"You want to study whenever it suits you."},{"key":"F","text":"You need to prepare for an exam."},{"key":"G","text":"You want to study with a teacher at a fixed time."},{"key":"H","text":"You want to compete against other people."},{"key":"I","text":"You are looking for a course for your child."},{"key":"J","text":"You want to meet learners from your own city."}],"questions":[{"id":"r-7","number":7,"kind":"match","prompt":"Text 7"},{"id":"r-8","number":8,"kind":"match","prompt":"Text 8"},{"id":"r-9","number":9,"kind":"match","prompt":"Text 9"},{"id":"r-10","number":10,"kind":"match","prompt":"Text 10"},{"id":"r-11","number":11,"kind":"match","prompt":"Text 11"},{"id":"r-12","number":12,"kind":"match","prompt":"Text 12"},{"id":"r-13","number":13,"kind":"match","prompt":"Text 13"},{"id":"r-14","number":14,"kind":"match","prompt":"Text 14"}]},{"id":"r3","index":3,"title":"Working from home","instruction":"Read the text and choose the correct heading for each paragraph from the list of headings. There are more headings than paragraphs, so you will not use all of them.","passage":[{"label":"I","text":"Until a few years ago, working from home was a privilege enjoyed by a small number of freelancers. Then, almost overnight, millions of office workers were told to stay at home and continue their jobs from kitchen tables and bedrooms. What began as an emergency soon became a normal way of working."},{"label":"II","text":"For many employees, the benefits were obvious. Without the daily journey to the office, they gained an hour or more every day. They also spent less on transport, lunches and work clothes, and some used the extra time to exercise or be with their children."},{"label":"III","text":"However, not everyone was happy. Many people found that they missed the small conversations in the corridor and the feeling of being part of a team. Young employees in particular said it was harder to learn from experienced colleagues when they could only see them on a screen."},{"label":"IV","text":"Employers have mixed feelings too. Some studies show that people working at home get more done, while others suggest the opposite. Much seems to depend on the type of job and on whether managers trust their staff to work without being watched."},{"label":"V","text":"Experts agree that a good home workplace makes a big difference. A proper desk and chair, natural light and a door that can be closed help people concentrate. It is also important to set clear hours, so that work does not take over the whole evening."},{"label":"VI","text":"For the future, most companies are choosing a mix of the two. Employees come to the office two or three days a week to meet and plan, and work from home on the other days. Many believe this combination offers the advantages of both systems."}],"choices":[{"key":"A","text":"Creating the right space"},{"key":"B","text":"The best of both worlds"},{"key":"C","text":"Mixed results for employers"},{"key":"D","text":"A sudden change"},{"key":"E","text":"Why cities are becoming empty"},{"key":"F","text":"Missing the office"},{"key":"G","text":"Time and money saved"},{"key":"H","text":"The end of business travel"}],"questions":[{"id":"r-15","number":15,"kind":"match","prompt":"Paragraph I"},{"id":"r-16","number":16,"kind":"match","prompt":"Paragraph II"},{"id":"r-17","number":17,"kind":"match","prompt":"Paragraph III"},{"id":"r-18","number":18,"kind":"match","prompt":"Paragraph IV"},{"id":"r-19","number":19,"kind":"match","prompt":"Paragraph V"},{"id":"r-20","number":20,"kind":"match","prompt":"Paragraph VI"}]},{"id":"r4","index":4,"title":"A guesthouse in the mountains","instruction":"Read the text. For questions 21–24, choose the correct answer A, B, C or D. For questions 25–29, decide if the statements agree with the information in the text.","passage":[{"label":"1","text":"Six years ago I had a good job in an office in Tashkent, a comfortable flat and a busy social life. I also had a constant headache from the traffic and the noise. One evening, stuck in a traffic jam for the third time that week, I decided that I wanted a quieter life, and a month later I handed in my notice."},{"label":"2","text":"I moved to a small village in the mountains where I had spent my summers as a child. My friends thought I was mad. The first winter was not easy. The cold I could deal with — I had bought plenty of wood — but I had never felt so lonely. Most of the young people had left for the cities, and the evenings were long and silent."},{"label":"3","text":"In spring I started to repair my grandparents’ old house, with the idea of renting rooms to visitors. For the first year only a few guests came. Then a travel blogger stayed for a week and wrote about the views, the bread from my clay oven and the walks to the waterfall. Within a month I was fully booked for the whole summer."},{"label":"4","text":"Electricity only arrived in the village ten years ago, and the road is still rough, but life here has changed a lot. Today I grow most of my own vegetables, and my neighbours sell honey, dried fruit and carpets to my guests. Most visitors come from Tashkent and Samarkand, although more people from abroad arrive every year."},{"label":"5","text":"Some people say tourism will spoil places like this, and I understand their fears. But I have seen how it has given families a reason to stay in the village instead of leaving. As long as we keep it small and respect the mountains, I believe visitors can help this place survive."}],"questions":[{"id":"r-21","number":21,"kind":"mcq","prompt":"Why did the writer leave Tashkent?","options":[{"key":"A","text":"She lost her job."},{"key":"B","text":"Her doctor told her to."},{"key":"C","text":"She wanted a quieter life."},{"key":"D","text":"Her family lived in the village."}]},{"id":"r-22","number":22,"kind":"mcq","prompt":"What did the writer find hardest in her first winter?","options":[{"key":"A","text":"the cold weather"},{"key":"B","text":"feeling lonely"},{"key":"C","text":"a lack of money"},{"key":"D","text":"repairing the house"}]},{"id":"r-23","number":23,"kind":"mcq","prompt":"The guesthouse became popular after","options":[{"key":"A","text":"a blogger wrote about it."},{"key":"B","text":"she advertised it on television."},{"key":"C","text":"a new road was built."},{"key":"D","text":"she opened a restaurant."}]},{"id":"r-24","number":24,"kind":"mcq","prompt":"In the writer’s opinion, tourism","options":[{"key":"A","text":"has already damaged the village."},{"key":"B","text":"helps families to stay in the village."},{"key":"C","text":"should be stopped completely."},{"key":"D","text":"only benefits hotel owners."}]},{"id":"r-25","number":25,"kind":"tfng","prompt":"The writer knew the village before she moved there."},{"id":"r-26","number":26,"kind":"tfng","prompt":"The writer’s husband did not want to move."},{"id":"r-27","number":27,"kind":"tfng","prompt":"There is still no electricity in the village."},{"id":"r-28","number":28,"kind":"tfng","prompt":"The writer produces most of her own vegetables."},{"id":"r-29","number":29,"kind":"tfng","prompt":"Most of the writer’s guests come from other countries."}]},{"id":"r5","index":5,"title":"The Aral Sea","instruction":"Read the text. For questions 30–33, fill in the missing information. Write no more than ONE WORD and / or A NUMBER. For questions 34–35, choose the correct answer A, B, C or D.","passage":[{"label":"1","text":"Sixty years ago, the Aral Sea was the fourth largest lake in the world. Fishing boats sailed from busy ports such as Muynak, and thousands of people worked in the fishing and canning industries. The sea was fed by two great rivers, the Amu Darya and the Syr Darya."},{"label":"2","text":"In the 1960s, planners decided to take water from these rivers to grow cotton in the desert. The plan produced a great deal of cotton, but very little water reached the sea any more. Year after year, the shoreline moved further away, and today the sea has lost about ninety per cent of its water."},{"label":"3","text":"The effects have been terrible. The fishing industry almost disappeared, and old ships now lie rusting in the sand, many kilometres from the water. Winds carry salt and dust from the dry seabed across the region, and local people have suffered from health problems."},{"label":"4","text":"There are, however, some signs of hope. In 2005, a dam was completed in Kazakhstan to keep water in the northern part of the sea. Since then, the water level there has risen, the water has become less salty and fish have returned. In Uzbekistan, millions of trees have been planted on the dry seabed to stop the dust from blowing."}],"questions":[{"id":"r-30","number":30,"kind":"gap","prompt":"The Aral Sea was once the … largest lake in the world."},{"id":"r-31","number":31,"kind":"gap","prompt":"Water from the rivers was used to grow"},{"id":"r-32","number":32,"kind":"gap","prompt":"The sea has lost about … per cent of its water."},{"id":"r-33","number":33,"kind":"gap","prompt":"In 2005, a … was completed to protect the northern part."},{"id":"r-34","number":34,"kind":"mcq","prompt":"What happened to the fishing industry?","options":[{"key":"A","text":"It moved to another sea."},{"key":"B","text":"It almost disappeared."},{"key":"C","text":"It grew larger."},{"key":"D","text":"It became illegal."}]},{"id":"r-35","number":35,"kind":"mcq","prompt":"What is the writer’s main purpose?","options":[{"key":"A","text":"to blame farmers for the disaster"},{"key":"B","text":"to explain the causes and effects of a disaster and some signs of hope"},{"key":"C","text":"to advertise tours to Muynak"},{"key":"D","text":"to compare the Aral Sea with other lakes"}]}]}],"writing":[{"id":"w1","index":1,"label":"Task 1","kind":"Letter","context":"You stayed at a hotel in Samarkand last weekend, but several things went wrong during your stay.","prompt":"Write an email to the hotel manager. In your email:\n- explain why you chose this hotel;\n- describe what went wrong;\n- say what you would like the hotel to do.\nWrite about 150 words in an appropriate format and style.","targetWords":150,"minWords":120,"weight":1},{"id":"w2","index":2,"label":"Task 2","kind":"Essay","prompt":"Some people think that governments should spend more money on public transport. Others believe that building better roads is more important.\n\nDiscuss both views and give your opinion. Write at least 250 words in an appropriate style and format.","targetWords":250,"minWords":250,"weight":2}],"speaking":[{"id":"s1","index":1,"part":"1.1","prompt":"What do you do? Do you work or study?","prepSec":5,"answerSec":30},{"id":"s2","index":2,"part":"1.1","prompt":"How do you usually travel around your city?","prepSec":5,"answerSec":30},{"id":"s3","index":3,"part":"1.1","prompt":"What was the last film or series you watched?","prepSec":5,"answerSec":30},{"id":"s4","index":4,"part":"1.2","prompt":"Compare the two pictures. What are the similarities and differences?","image":"Picture A: students studying together in a library · Picture B: a student studying alone at home with a laptop","prepSec":10,"answerSec":45},{"id":"s5","index":5,"part":"1.2","prompt":"Do you prefer studying alone or with other people? Why?","image":"Picture A: students studying together in a library · Picture B: a student studying alone at home with a laptop","prepSec":5,"answerSec":30},{"id":"s6","index":6,"part":"1.2","prompt":"How has technology changed the way students study?","image":"Picture A: students studying together in a library · Picture B: a student studying alone at home with a laptop","prepSec":5,"answerSec":30},{"id":"s7","index":7,"part":"2","prompt":"Describe an older person you admire. Say who they are, what they have done and why you admire them.","image":"An old man telling stories to his grandchildren","prepSec":60,"answerSec":120},{"id":"s8","index":8,"part":"3","prompt":"Mobile phones should be banned in schools. For: phones distract students and cause cheating. Against: phones are useful for learning and for safety. Give arguments for and against this statement and say what you think.","prepSec":60,"answerSec":120}]}$json$::jsonb)
