insert into public.test_keys (test_id, keys, scripts)
values ('t11', $json${"l-1":{"answer":"A"},"l-2":{"answer":"B"},"l-3":{"answer":"A"},"l-4":{"answer":"C"},"l-5":{"answer":"B","explanation":"\"Tea or coffee?\" — tanlov savoli, shuning uchun \"Yes, please\" mos kelmaydi."},"l-6":{"answer":"A"},"l-7":{"answer":"B"},"l-8":{"answer":"C"},"l-9":{"answer":"6|six","explanation":"Avval 4 ta edi, hozir 6 ta."},"l-10":{"answer":"third|3rd"},"l-11":{"answer":"librarian"},"l-12":{"answer":"2000|2,000|two thousand"},"l-13":{"answer":"food"},"l-14":{"answer":"Sunday","explanation":"Juma kuni kech soatgacha ochiq — bu chalg'ituvchi ma'lumot."},"l-15":{"answer":"E"},"l-16":{"answer":"A","explanation":"Pul almashtirish tilga olinadi, lekin \"boarding gate\" va \"passport\" — aeroport."},"l-17":{"answer":"F"},"l-18":{"answer":"D"},"l-19":{"answer":"E"},"l-20":{"answer":"G"},"l-21":{"answer":"D"},"l-22":{"answer":"A"},"l-23":{"answer":"C","explanation":"\"Directly opposite the main entrance\" — kiraverish qarshisida, yo'lning shimoliy tomonida."},"l-24":{"answer":"A"},"l-25":{"answer":"B","explanation":"Chodirni Bekzod olib keladi, chiroq esa uyda bor."},"l-26":{"answer":"A"},"l-27":{"answer":"C"},"l-28":{"answer":"B"},"l-29":{"answer":"B"},"l-30":{"answer":"silk"},"l-31":{"answer":"nets"},"l-32":{"answer":"prisoners"},"l-33":{"answer":"strong"},"l-34":{"answer":"parchment"},"l-35":{"answer":"wood"},"r-1":{"answer":"adults"},"r-2":{"answer":"language"},"r-3":{"answer":"practise|practice"},"r-4":{"answer":"difference"},"r-5":{"answer":"mistakes"},"r-6":{"answer":"partner"},"r-7":{"answer":"G","explanation":"\"Certificate\" imtihon degani emas — F javobi 11-matnga tegishli."},"r-8":{"answer":"C"},"r-9":{"answer":"E"},"r-10":{"answer":"I"},"r-11":{"answer":"F"},"r-12":{"answer":"A"},"r-13":{"answer":"B"},"r-14":{"answer":"H"},"r-15":{"answer":"D"},"r-16":{"answer":"G"},"r-17":{"answer":"F"},"r-18":{"answer":"C"},"r-19":{"answer":"A"},"r-20":{"answer":"B"},"r-21":{"answer":"C"},"r-22":{"answer":"B","explanation":"Sovuq bilan kurashgan — o'tin olgan, eng qiyini yolg'izlik bo'lgan."},"r-23":{"answer":"A"},"r-24":{"answer":"B"},"r-25":{"answer":"True"},"r-26":{"answer":"No Information"},"r-27":{"answer":"False"},"r-28":{"answer":"True"},"r-29":{"answer":"False","explanation":"Mehmonlarning ko'pchiligi Toshkent va Samarqanddan."},"r-30":{"answer":"fourth|4th"},"r-31":{"answer":"cotton"},"r-32":{"answer":"90|ninety"},"r-33":{"answer":"dam"},"r-34":{"answer":"B"},"r-35":{"answer":"B"}}$json$::jsonb, $json$[{"partId":"l1","lines":[{"voice":"narrator","text":"Part one. You will hear some sentences. Choose the correct reply to each sentence."},{"voice":"man","text":"Excuse me, is anyone sitting here?","question":1},{"voice":"woman","text":"What time does the next bus to the city centre leave?","question":2},{"voice":"man","text":"I'm so sorry I'm late, the traffic was terrible.","question":3},{"voice":"woman","text":"Could you help me carry these boxes upstairs?","question":4},{"voice":"man","text":"Would you like tea or coffee?","question":5},{"voice":"woman","text":"Guess what? I've just been offered a place at university!","question":6},{"voice":"man","text":"Do you mind if I borrow your pen for a minute?","question":7},{"voice":"woman","text":"So, how was your holiday in Khiva?","question":8},{"voice":"narrator","text":"That is the end of part one."}]},{"partId":"l2","lines":[{"voice":"narrator","text":"Part two. You will hear a librarian giving a tour. Fill in the missing information. Write one word and, or, a number for each answer."},{"voice":"woman","text":"Hello, everyone, and welcome to the Central Library. I'll show you around and explain how everything works."},{"voice":"woman","text":"With your membership card you can borrow books for three weeks. Until last year the limit was four books, but now you can take up to six books at a time.","question":9},{"voice":"woman","text":"The computers are on the second floor, and if you need somewhere quiet to work with friends, the study rooms are on the third floor. You can book them online.","question":10},{"voice":"woman","text":"There are printers on every floor. They aren't free, I'm afraid. To use one, you need a code, which you can get from the librarian at the desk.","question":11},{"voice":"woman","text":"Please return your books on time. If a book is late, the fine is two thousand som per day, so it's worth setting a reminder on your phone.","question":12},{"voice":"woman","text":"On the ground floor there's a quiet zone. You can bring a bottle of water, but no food is allowed there, because it attracts insects.","question":13},{"voice":"woman","text":"Finally, opening hours. We're open late on Fridays, until nine, and the library is closed every Sunday. Enjoy your reading!","question":14},{"voice":"narrator","text":"That is the end of part two."}]},{"partId":"l3","lines":[{"voice":"narrator","text":"Part three. You will hear people speaking in different situations. Match each speaker to the place where the speaker is. There are two extra places which you do not need to use."},{"voice":"narrator","text":"Speaker 1.","question":15},{"voice":"man","text":"Good evening. Are you ready to order? Today's special is lamb with rice and vegetables, and our chef recommends the apricot dessert. Can I get you anything to drink first?"},{"voice":"narrator","text":"Speaker 2.","question":16},{"voice":"woman","text":"Your boarding gate is number twelve, and boarding starts in forty minutes. Please keep your passport ready. If you need to change money, there's an exchange office just after security."},{"voice":"narrator","text":"Speaker 3.","question":17},{"voice":"man2","text":"If you'd like to watch the penguins being fed, come back here at two o'clock. And please remember, don't give the animals any of your own food. It can make them very ill."},{"voice":"narrator","text":"Speaker 4.","question":18},{"voice":"woman2","text":"Right, open your mouth and say 'ah'. Yes, your throat is quite red. Take these tablets twice a day after meals, drink plenty of water, and come back to see me if you're not better in a week."},{"voice":"narrator","text":"That is the end of part three."}]},{"partId":"l4","lines":[{"voice":"narrator","text":"Part four. You will hear someone giving a talk. Label the places on the map. There are three extra options which you do not need to use."},{"voice":"man","text":"Welcome to the university. We're standing at the main entrance, on the south side of Campus Road. Let me show you where a few important places are."},{"voice":"man","text":"If you're hungry, the canteen is very close. It's next to the main entrance, on its east side, on this side of the road.","question":19},{"voice":"man","text":"The sports field is down Library Walk. Walk south all the way to the end, and you'll find it on your left-hand side.","question":20},{"voice":"man","text":"For the science building, go east along Campus Road and turn left into Park Lane. Walk north, and the science building is on your right.","question":21},{"voice":"man","text":"The bookshop is at the far western end of Campus Road, on the north side.","question":22},{"voice":"man","text":"And finally, the student office, where you'll collect your ID card. It's directly opposite the main entrance, on the other side of Campus Road.","question":23},{"voice":"narrator","text":"That is the end of part four."}]},{"partId":"l5","lines":[{"voice":"narrator","text":"Part five. You will hear three extracts. Choose the correct answer for each question. There are two questions for each extract."},{"voice":"narrator","text":"Extract one. You will hear two friends planning a camping trip."},{"voice":"man","text":"So, Zarina, are we still going camping in the mountains this weekend?"},{"voice":"woman","text":"Actually, I've changed my mind. It's going to be really cold up there. Let's camp by the lake instead. It's warmer, and we can swim.","question":24},{"voice":"woman","text":"You're bringing your tent, aren't you? Good. I've got a torch at home, but my old sleeping bag is broken, so I'll buy a new one tomorrow.","question":25},{"voice":"narrator","text":"Extract two. You will hear part of an interview with a young app developer."},{"voice":"woman2","text":"Malika, your app has been downloaded half a million times. Where did the idea come from?"},{"voice":"woman3","text":"From my grandmother, really. She takes several kinds of medicine and kept forgetting which ones she'd taken. So I built a simple app that reminds her. It wasn't a school project or anything like that.","question":26},{"voice":"woman3","text":"I learnt to code on my own, and investors found me quite quickly. The hard part now is time. I'm still at university, and balancing my studies and the company is really difficult.","question":27},{"voice":"narrator","text":"Extract three. You will hear two neighbours talking."},{"voice":"man2","text":"Excuse me, do you live in flat twelve? The dog next door has been barking all night again. It's not the music, that stopped weeks ago, but I just can't sleep.","question":28},{"voice":"woman","text":"I know, it's terrible for me too. I don't want to call the police. Why don't we go and talk to the owner together this evening? I'm sure she doesn't realise.","question":29},{"voice":"narrator","text":"That is the end of part five."}]},{"partId":"l6","lines":[{"voice":"narrator","text":"Part six. You will hear a part of a lecture. Fill in the missing information. Write no more than one word for each answer."},{"voice":"man3","text":"Today we're going to look at the history of something we use every day without thinking about it: paper."},{"voice":"man3","text":"Before paper was invented, people in China wrote on strips of bamboo, which were heavy, and on silk, which was very expensive.","question":30},{"voice":"man3","text":"Around two thousand years ago, the first real paper was made in China from tree bark, old pieces of cloth and even old fishing nets.","question":31},{"voice":"man3","text":"For centuries, the method was kept secret. According to tradition, it reached Samarkand in the eighth century, when Chinese prisoners taught local craftsmen how to make it.","question":32},{"voice":"man3","text":"Samarkand paper soon became famous across the Islamic world. It was smooth and strong, and it was used for books, letters and maps.","question":33},{"voice":"man3","text":"When paper finally arrived in Europe, it slowly replaced parchment, which was made from animal skin and cost a great deal.","question":34},{"voice":"man3","text":"Today, of course, most paper is made from wood, although more and more is now recycled.","question":35},{"voice":"narrator","text":"That is the end of part six."}]}]$json$::jsonb)
on conflict (test_id) do update set keys = excluded.keys, scripts = excluded.scripts;

insert into public.tests (id, number, title, format_month, format_year, is_new, is_free, is_pro, content)
values ('t12', 12, 'Mock Test #12', 8, 2026, false, true, false, $json${"sections":[{"kind":"listening","title":"Listening","parts":6,"questions":35,"minutes":35},{"kind":"reading","title":"Reading","parts":5,"questions":35,"minutes":60},{"kind":"writing","title":"Writing","parts":2,"minutes":60},{"kind":"speaking","title":"Speaking","parts":3,"minutes":15,"approx":true}],"listening":[{"id":"l1","index":1,"instruction":"You will hear some sentences. Choose the correct reply to each sentence.","emphasis":"A, B or C","durationSec":51,"questions":[{"id":"l-1","number":1,"kind":"mcq","prompt":"","options":[{"key":"A","text":"Yes, of course."},{"key":"B","text":"It costs ten dollars."},{"key":"C","text":"I paid yesterday."}]},{"id":"l-2","number":2,"kind":"mcq","prompt":"","options":[{"key":"A","text":"I'll open the door."},{"key":"B","text":"I think they're on the kitchen table."},{"key":"C","text":"No, I haven't got a car."}]},{"id":"l-3","number":3,"kind":"mcq","prompt":"","options":[{"key":"A","text":"Good idea, it gets busy on Fridays."},{"key":"B","text":"It was delicious."},{"key":"C","text":"Yes, I booked it last week."}]},{"id":"l-4","number":4,"kind":"mcq","prompt":"","options":[{"key":"A","text":"See you there!"},{"key":"B","text":"Thanks for coming."},{"key":"C","text":"That's a pity, maybe next time."}]},{"id":"l-5","number":5,"kind":"mcq","prompt":"","options":[{"key":"A","text":"Yes, it's the third stop."},{"key":"B","text":"It's a fast train."},{"key":"C","text":"No, I'm going there too."}]},{"id":"l-6","number":6,"kind":"mcq","prompt":"","options":[{"key":"A","text":"I've already had lunch."},{"key":"B","text":"Sounds great, let's go to the park."},{"key":"C","text":"I walked there."}]},{"id":"l-7","number":7,"kind":"mcq","prompt":"","options":[{"key":"A","text":"Let me get you a plaster."},{"key":"B","text":"It's very sharp."},{"key":"C","text":"Well done!"}]},{"id":"l-8","number":8,"kind":"mcq","prompt":"","options":[{"key":"A","text":"She teaches maths."},{"key":"B","text":"I'll ask her."},{"key":"C","text":"She's strict, but her lessons are interesting."}]}],"audio":"t12/l1.mp3","audioAt":{"1":8,"2":12,"3":17,"4":23,"5":27,"6":34,"7":38,"8":43}},{"id":"l2","index":2,"title":"Summer Language Camp — information","instruction":"You will hear a camp director talking to parents. Fill in the missing information. Write","emphasis":"ONE WORD and / or A NUMBER","durationSec":85,"questions":[{"id":"l-9","number":9,"kind":"gap","prompt":"The camp starts on … July"},{"id":"l-10","number":10,"kind":"gap","prompt":"Each room is for … students"},{"id":"l-11","number":11,"kind":"gap","prompt":"For the pool, students must bring a swimming"},{"id":"l-12","number":12,"kind":"gap","prompt":"Saturday trip: a walk to a"},{"id":"l-13","number":13,"kind":"gap","prompt":"Phones can only be used in the"},{"id":"l-14","number":14,"kind":"gap","prompt":"The price includes everything except"}],"audio":"t12/l2.mp3","audioAt":{"9":20,"10":31,"11":42,"12":52,"13":63,"14":71}},{"id":"l3","index":3,"instruction":"You will hear people speaking in different situations. Match each speaker (15–18) to the place where the speaker is (A–F). There are","emphasis":"TWO EXTRA places","durationSec":70,"choices":[{"key":"A","text":"at a hairdresser's"},{"key":"B","text":"in a library"},{"key":"C","text":"at a petrol station"},{"key":"D","text":"in a clothes shop"},{"key":"E","text":"at a swimming pool"},{"key":"F","text":"at the dentist's"}],"questions":[{"id":"l-15","number":15,"kind":"match","prompt":"Speaker 1"},{"id":"l-16","number":16,"kind":"match","prompt":"Speaker 2"},{"id":"l-17","number":17,"kind":"match","prompt":"Speaker 3"},{"id":"l-18","number":18,"kind":"match","prompt":"Speaker 4"}],"audio":"t12/l3.mp3","audioAt":{"15":14,"16":28,"17":43,"18":54}},{"id":"l4","index":4,"instruction":"You will hear someone giving a talk. Label the places (19–23) on the map (A–H). There are","emphasis":"THREE extra options","durationSec":65,"choices":[{"key":"A","text":""},{"key":"B","text":""},{"key":"C","text":""},{"key":"D","text":""},{"key":"E","text":""},{"key":"F","text":""},{"key":"G","text":""},{"key":"H","text":""}],"map":{"width":320,"height":240,"roads":[{"points":[[10,130],[310,130]]},{"points":[[200,10],[200,130]]},{"points":[[80,130],[80,230]]}],"blocks":[{"x":18,"y":84,"w":52,"h":32,"letter":"A"},{"x":100,"y":84,"w":60,"h":32,"name":"Clock tower"},{"x":130,"y":28,"w":52,"h":32,"letter":"D"},{"x":216,"y":28,"w":52,"h":32,"letter":"B"},{"x":216,"y":84,"w":52,"h":32,"letter":"C"},{"x":14,"y":146,"w":50,"h":32,"letter":"E"},{"x":96,"y":146,"w":60,"h":32,"letter":"F"},{"x":96,"y":192,"w":60,"h":32,"letter":"G"},{"x":240,"y":146,"w":60,"h":32,"letter":"H"}],"labels":[{"x":270,"y":134,"text":"Bazaar Street"},{"x":200,"y":20,"text":"Mosque Road"},{"x":80,"y":236,"text":"Garden Street"}]},"questions":[{"id":"l-19","number":19,"kind":"match","prompt":"Carpet shop"},{"id":"l-20","number":20,"kind":"match","prompt":"Tea house"},{"id":"l-21","number":21,"kind":"match","prompt":"Pharmacy"},{"id":"l-22","number":22,"kind":"match","prompt":"Museum"},{"id":"l-23","number":23,"kind":"match","prompt":"Hotel"}],"audio":"t12/l4.mp3","audioAt":{"19":21,"20":28,"21":38,"22":46,"23":53}},{"id":"l5","index":5,"instruction":"You will hear three extracts. Choose the correct answer (A, B or C) for each question. There are","emphasis":"TWO questions for each extract","durationSec":111,"questions":[{"id":"l-24","number":24,"kind":"mcq","prompt":"What topic have the students chosen for their project?","options":[{"key":"A","text":"recycling"},{"key":"B","text":"public transport"},{"key":"C","text":"local history"}],"group":"Extract One"},{"id":"l-25","number":25,"kind":"mcq","prompt":"Who will give the presentation?","options":[{"key":"A","text":"Anvar"},{"key":"B","text":"Dilnoza"},{"key":"C","text":"both of them"}],"group":"Extract One"},{"id":"l-26","number":26,"kind":"mcq","prompt":"Why did Nigora start running?","options":[{"key":"A","text":"to lose weight"},{"key":"B","text":"to get stronger after an illness"},{"key":"C","text":"because a friend advised her"}],"group":"Extract Two"},{"id":"l-27","number":27,"kind":"mcq","prompt":"What is her main advice for beginners?","options":[{"key":"A","text":"Buy expensive running shoes."},{"key":"B","text":"Run every single day."},{"key":"C","text":"Increase the distance slowly."}],"group":"Extract Two"},{"id":"l-28","number":28,"kind":"mcq","prompt":"What is wrong with the customer’s phone?","options":[{"key":"A","text":"The screen is cracked."},{"key":"B","text":"The battery runs out quickly."},{"key":"C","text":"It is the wrong colour."}],"group":"Extract Three"},{"id":"l-29","number":29,"kind":"mcq","prompt":"What will the shop do?","options":[{"key":"A","text":"give her money back"},{"key":"B","text":"repair the phone"},{"key":"C","text":"give her a new phone"}],"group":"Extract Three"}],"audio":"t12/l5.mp3","audioAt":{"24":22,"25":35,"26":56,"27":71,"28":87,"29":96}},{"id":"l6","index":6,"title":"The life of honey bees","instruction":"You will hear a part of a lecture. Fill in the missing information. Write","emphasis":"no more than ONE WORD","durationSec":69,"questions":[{"id":"l-30","number":30,"kind":"gap","prompt":"Each colony has only one"},{"id":"l-31","number":31,"kind":"gap","prompt":"Workers show where flowers are by performing a"},{"id":"l-32","number":32,"kind":"gap","prompt":"Honey lasts a long time because it contains very little"},{"id":"l-33","number":33,"kind":"gap","prompt":"Bees keep the hive at a steady"},{"id":"l-34","number":34,"kind":"gap","prompt":"About a third of our food depends on"},{"id":"l-35","number":35,"kind":"gap","prompt":"Bees are threatened by disease and"}],"audio":"t12/l6.mp3","audioAt":{"30":15,"31":23,"32":33,"33":42,"34":50,"35":58}}],"reading":[{"id":"r1","index":1,"title":"The benefits of walking","instruction":"Read the text. Fill in each gap with ONE word. You must use a word which is somewhere in the rest of the text.","passage":[{"label":"1","text":"Many people spend hours sitting at a desk every day. Walking is one of the easiest ways to stay healthy, and you do not need special (1) ______ or a gym membership — just a good pair of shoes. Doctors say that thirty minutes of walking a (2) ______ can lower the risk of heart disease."},{"label":"2","text":"Walking is also good for the mind. People who walk regularly often feel less (3) ______ and sleep better. If you live near your office, try walking to (4) ______ instead of taking the bus. You can also walk with friends or family; it is a good way to (5) ______ time with people you love."},{"label":"3","text":"Many cities now have special paths for walkers, and some offer free guided walks every (6) ______. So put on your shoes: you need no equipment, just thirty minutes a day. Walking to work keeps you fit and less stressed. Why not join a guided walk this weekend?"}],"questions":[{"id":"r-1","number":1,"kind":"gap","prompt":"You do not need special (1) ______ or a gym membership."},{"id":"r-2","number":2,"kind":"gap","prompt":"Thirty minutes of walking a (2) ______ can lower the risk of heart disease."},{"id":"r-3","number":3,"kind":"gap","prompt":"People who walk regularly often feel less (3) ______."},{"id":"r-4","number":4,"kind":"gap","prompt":"Try walking to (4) ______ instead of taking the bus."},{"id":"r-5","number":5,"kind":"gap","prompt":"It is a good way to (5) ______ time with people you love."},{"id":"r-6","number":6,"kind":"gap","prompt":"Some cities offer free guided walks every (6) ______."}]},{"id":"r2","index":2,"title":"Places to eat","instruction":"Read the texts 7–14 and the statements A–J. Decide which text matches the situation in each statement. Each statement can be used ONCE only. There are TWO extra statements.","passage":[{"label":"7","text":"GREEN LEAF — Vegetarian dishes only. Fresh salads, soups and homemade bread every day."},{"label":"8","text":"PIZZA EXPRESS — Order online and we deliver to your door within 30 minutes. Delivery is always free."},{"label":"9","text":"SAMARKAND HOUSE — Traditional dishes and live music by local musicians every Friday and Saturday evening."},{"label":"10","text":"FAMILY CORNER — A safe play area for little ones, high chairs and a special children’s menu."},{"label":"11","text":"MORNING BAKERY — Open from 6 am. Fresh bread, pastries and the best coffee in town to start your day."},{"label":"12","text":"SKY TERRACE — A rooftop restaurant on the 20th floor with views across the whole city."},{"label":"13","text":"BUDGET BITES — Big portions at small prices. Students get 20% off with a student card."},{"label":"14","text":"CHEF’S TABLE — Join our chef in the kitchen for a two-hour class, then enjoy the dinner you have cooked."}],"choices":[{"key":"A","text":"You want breakfast very early."},{"key":"B","text":"You need a private room for a business meeting."},{"key":"C","text":"You want food brought to your home."},{"key":"D","text":"You would like a good view while you eat."},{"key":"E","text":"You do not eat meat."},{"key":"F","text":"You want to learn how to prepare a dish."},{"key":"G","text":"You are a student with little money."},{"key":"H","text":"You want to eat after midnight."},{"key":"I","text":"You would like to listen to live music."},{"key":"J","text":"You are eating out with young children."}],"questions":[{"id":"r-7","number":7,"kind":"match","prompt":"Text 7"},{"id":"r-8","number":8,"kind":"match","prompt":"Text 8"},{"id":"r-9","number":9,"kind":"match","prompt":"Text 9"},{"id":"r-10","number":10,"kind":"match","prompt":"Text 10"},{"id":"r-11","number":11,"kind":"match","prompt":"Text 11"},{"id":"r-12","number":12,"kind":"match","prompt":"Text 12"},{"id":"r-13","number":13,"kind":"match","prompt":"Text 13"},{"id":"r-14","number":14,"kind":"match","prompt":"Text 14"}]},{"id":"r3","index":3,"title":"Plastic in the ocean","instruction":"Read the text and choose the correct heading for each paragraph from the list of headings. There are more headings than paragraphs, so you will not use all of them.","passage":[{"label":"I","text":"Every year, millions of tonnes of plastic end up in the world’s oceans. Scientists have found plastic on remote islands, at the bottom of the deepest ocean trenches and even in Arctic ice. If nothing changes, some experts warn that there may soon be more plastic than fish in parts of the sea."},{"label":"II","text":"Most of this plastic does not come from ships. It starts its journey on land, as bottles, bags and packaging that are dropped in the street or lost from rubbish dumps. Rain washes it into rivers, and the rivers carry it all the way to the sea."},{"label":"III","text":"For sea creatures, plastic can be deadly. Turtles mistake floating bags for jellyfish, seabirds feed bottle tops to their chicks, and whales have been found with kilograms of plastic in their stomachs. Old fishing nets continue to trap fish and dolphins for years."},{"label":"IV","text":"Over time, sunlight and waves break plastic into tiny pieces called microplastics. They are often smaller than a grain of rice, and they are eaten by fish and shellfish. Scientists are now studying what happens when these particles reach the food on our plates."},{"label":"V","text":"Some governments are taking action. Many countries have banned or taxed thin plastic bags, and in several of them the number of bags used has fallen dramatically within a few years. Others have banned plastic straws and cups, or made companies pay for collecting their packaging."},{"label":"VI","text":"Individuals can help too. Carrying a reusable bag and water bottle, saying no to straws and sorting rubbish for recycling may seem small, but when millions of people do them, the effect is huge. Every bottle that is recycled is one less that might reach the sea."}],"choices":[{"key":"A","text":"Too small to see"},{"key":"B","text":"Laws that make a difference"},{"key":"C","text":"From land to sea"},{"key":"D","text":"The history of plastic"},{"key":"E","text":"Small steps at home"},{"key":"F","text":"A problem of enormous size"},{"key":"G","text":"Dangerous for wildlife"},{"key":"H","text":"Cleaner beaches for tourists"}],"questions":[{"id":"r-15","number":15,"kind":"match","prompt":"Paragraph I"},{"id":"r-16","number":16,"kind":"match","prompt":"Paragraph II"},{"id":"r-17","number":17,"kind":"match","prompt":"Paragraph III"},{"id":"r-18","number":18,"kind":"match","prompt":"Paragraph IV"},{"id":"r-19","number":19,"kind":"match","prompt":"Paragraph V"},{"id":"r-20","number":20,"kind":"match","prompt":"Paragraph VI"}]},{"id":"r4","index":4,"title":"My father’s car","instruction":"Read the text. For questions 21–24, choose the correct answer A, B, C or D. For questions 25–29, decide if the statements agree with the information in the text.","passage":[{"label":"1","text":"Three years ago, my father and I were driving past a farm outside the city when he suddenly stopped the car. In a field behind the farmhouse, half covered with grass, stood an old blue Moskvich. My father walked around it twice and then told me, with a strange smile, that it was exactly the same model as his very first car."},{"label":"2","text":"The farmer was happy to sell it for almost nothing. I was eighteen, and I knew nothing about engines, but my father said we would bring it back to life together. I thought it would take a few months. In the end, it took us just over two years of weekends and evenings in the garage."},{"label":"3","text":"The engine was easier than we expected; my father still remembered how everything worked. The real problem was finding spare parts. The car had not been produced for decades, so we searched markets, asked old mechanics and finally ordered some parts from collectors abroad. Each time a box arrived, it felt like a holiday."},{"label":"4","text":"Last spring we drove the car to a classic car show in Tashkent. We did not win a prize, but something better happened. All day, older visitors came to tell us stories about their own Moskvich: a wedding, a first trip to the sea, a broken-down engine in the desert. My father listened to every story."},{"label":"5","text":"I learned more in those two years than in any classroom — not only about cars, but about patience and about my father. He is already looking for our next project. This time, he says, it will be an old motorbike."}],"questions":[{"id":"r-21","number":21,"kind":"mcq","prompt":"Where did the writer and his father find the car?","options":[{"key":"A","text":"at a car show"},{"key":"B","text":"in a field behind a farm"},{"key":"C","text":"in an advertisement online"},{"key":"D","text":"in the father’s garage"}]},{"id":"r-22","number":22,"kind":"mcq","prompt":"Why did the father want the car?","options":[{"key":"A","text":"He wanted to sell it later."},{"key":"B","text":"It was the same model as his first car."},{"key":"C","text":"He wanted to win a competition."},{"key":"D","text":"His son had asked for a car."}]},{"id":"r-23","number":23,"kind":"mcq","prompt":"What was the most difficult part of the project?","options":[{"key":"A","text":"repairing the engine"},{"key":"B","text":"painting the car"},{"key":"C","text":"finding spare parts"},{"key":"D","text":"paying for the car"}]},{"id":"r-24","number":24,"kind":"mcq","prompt":"At the car show,","options":[{"key":"A","text":"the car won first prize."},{"key":"B","text":"the car broke down."},{"key":"C","text":"older visitors shared their memories."},{"key":"D","text":"someone offered to buy the car."}]},{"id":"r-25","number":25,"kind":"tfng","prompt":"The writer had experience of repairing cars before the project."},{"id":"r-26","number":26,"kind":"tfng","prompt":"The project took more than a year."},{"id":"r-27","number":27,"kind":"tfng","prompt":"The writer’s mother helped to paint the car."},{"id":"r-28","number":28,"kind":"tfng","prompt":"Some parts came from other countries."},{"id":"r-29","number":29,"kind":"tfng","prompt":"They are planning to repair another car."}]},{"id":"r5","index":5,"title":"The saiga antelope","instruction":"Read the text. For questions 30–33, fill in the missing information. Write no more than ONE WORD and / or A NUMBER. For questions 34–35, choose the correct answer A, B, C or D.","passage":[{"label":"1","text":"The saiga is one of the strangest-looking animals of the Central Asian steppe. Its large, soft nose hangs down over its mouth and works like a filter, cleaning the dusty air in summer and warming the cold air in winter."},{"label":"2","text":"Saigas travel long distances across the grasslands in huge herds, sometimes tens of thousands of animals together. Their movements follow the seasons, as they search for fresh grass and safe places to give birth to their young."},{"label":"3","text":"In the last century, the saiga came close to extinction. Hunters killed the males for their horns, which were sold for use in traditional medicine, and the population fell dramatically. Then, in 2015, a disease spread through the herds in Kazakhstan and killed more than half of the population in just a few weeks."},{"label":"4","text":"Yet the story has a hopeful ending. Strict protection from hunting, new nature reserves and the work of rangers have allowed the saiga to recover. In Kazakhstan, numbers have grown to more than a million, and conservationists now see the saiga as an example of how quickly nature can return when it is given a chance."}],"questions":[{"id":"r-30","number":30,"kind":"gap","prompt":"The saiga’s unusual … filters the dusty air."},{"id":"r-31","number":31,"kind":"gap","prompt":"Saigas travel across the steppe in large"},{"id":"r-32","number":32,"kind":"gap","prompt":"In 2015, a … killed more than half of the saigas."},{"id":"r-33","number":33,"kind":"gap","prompt":"Male saigas were hunted for their"},{"id":"r-34","number":34,"kind":"mcq","prompt":"What has helped the saiga population to recover?","options":[{"key":"A","text":"keeping saigas in zoos"},{"key":"B","text":"protection from hunting"},{"key":"C","text":"moving them to other countries"},{"key":"D","text":"feeding them in winter"}]},{"id":"r-35","number":35,"kind":"mcq","prompt":"What is the writer’s main purpose?","options":[{"key":"A","text":"to describe the dangers to an animal and its recovery"},{"key":"B","text":"to criticise traditional medicine"},{"key":"C","text":"to compare the saiga with other antelopes"},{"key":"D","text":"to encourage tourists to visit the steppe"}]}]}],"writing":[{"id":"w1","index":1,"label":"Task 1","kind":"Letter","context":"Your local sports centre has asked its members for ideas on how to improve its services.","prompt":"Write an email to the manager of the sports centre. In your email:\n- say how long you have been a member and what you use;\n- describe two problems you have noticed;\n- suggest how the centre could improve.\nWrite about 150 words in an appropriate format and style.","targetWords":150,"minWords":120,"weight":1},{"id":"w2","index":2,"label":"Task 2","kind":"Essay","prompt":"Some people prefer to live in a big city, while others believe that life in the countryside is better.\n\nDiscuss both views and give your opinion. Write at least 250 words in an appropriate style and format.","targetWords":250,"minWords":250,"weight":2}],"speaking":[{"id":"s1","index":1,"part":"1.1","prompt":"What do you usually do in the mornings before work or study?","prepSec":5,"answerSec":30},{"id":"s2","index":2,"part":"1.1","prompt":"Do you prefer spending time indoors or outdoors? Why?","prepSec":5,"answerSec":30},{"id":"s3","index":3,"part":"1.1","prompt":"Tell me about a place in your town that you like to visit.","prepSec":5,"answerSec":30},{"id":"s4","index":4,"part":"1.2","prompt":"Compare the two pictures. What are the similarities and differences?","image":"Picture A: a family eating dinner together at home · Picture B: friends eating fast food in a café","prepSec":10,"answerSec":45},{"id":"s5","index":5,"part":"1.2","prompt":"Which kind of meal do you enjoy more? Why?","image":"Picture A: a family eating dinner together at home · Picture B: friends eating fast food in a café","prepSec":5,"answerSec":30},{"id":"s6","index":6,"part":"1.2","prompt":"Do you think families spend less time together than in the past?","image":"Picture A: a family eating dinner together at home · Picture B: friends eating fast food in a café","prepSec":5,"answerSec":30},{"id":"s7","index":7,"part":"2","prompt":"Talk about a time when you helped someone or your community. Say what you did, why you did it and how you felt afterwards.","image":"A group of volunteers planting trees in a city park","prepSec":60,"answerSec":120},{"id":"s8","index":8,"part":"3","prompt":"Every student should learn to play a musical instrument at school. For: music improves concentration and creativity. Against: it takes time away from important subjects. Give arguments for and against this statement and say what you think.","prepSec":60,"answerSec":120}]}$json$::jsonb)
