values ('t12', $json${"l-1":{"answer":"A"},"l-2":{"answer":"B"},"l-3":{"answer":"A"},"l-4":{"answer":"C"},"l-5":{"answer":"A"},"l-6":{"answer":"B"},"l-7":{"answer":"A"},"l-8":{"answer":"C","explanation":"Fikr so'ralmoqda (\"What do you think of...?\"), shuning uchun baho beradigan javob kerak."},"l-9":{"answer":"15|15th|fifteenth","explanation":"1-iyul — ro'yxatdan o'tish oxirgi kuni, lager esa 15-iyulda boshlanadi."},"l-10":{"answer":"3|three"},"l-11":{"answer":"cap"},"l-12":{"answer":"waterfall"},"l-13":{"answer":"evening|evenings"},"l-14":{"answer":"insurance"},"l-15":{"answer":"D"},"l-16":{"answer":"E"},"l-17":{"answer":"A","explanation":"\"Wash first\", \"a little off the sides\" — sartaroshxona iboralari."},"l-18":{"answer":"C"},"l-19":{"answer":"A"},"l-20":{"answer":"D"},"l-21":{"answer":"C","explanation":"Burchakda, Mosque Road ning sharqiy tomonida. B ham sharqda, lekin yuqorida."},"l-22":{"answer":"G"},"l-23":{"answer":"H"},"l-24":{"answer":"A"},"l-25":{"answer":"C"},"l-26":{"answer":"B"},"l-27":{"answer":"C","explanation":"Qimmat poyabzal shart emas, har kuni yugurish ham noto'g'ri deydi."},"l-28":{"answer":"B"},"l-29":{"answer":"C"},"l-30":{"answer":"queen"},"l-31":{"answer":"dance"},"l-32":{"answer":"water"},"l-33":{"answer":"temperature"},"l-34":{"answer":"pollination"},"l-35":{"answer":"pesticides|chemicals"},"r-1":{"answer":"equipment"},"r-2":{"answer":"day"},"r-3":{"answer":"stressed"},"r-4":{"answer":"work"},"r-5":{"answer":"spend"},"r-6":{"answer":"weekend"},"r-7":{"answer":"E"},"r-8":{"answer":"C"},"r-9":{"answer":"I"},"r-10":{"answer":"J"},"r-11":{"answer":"A"},"r-12":{"answer":"D"},"r-13":{"answer":"G"},"r-14":{"answer":"F"},"r-15":{"answer":"F"},"r-16":{"answer":"C"},"r-17":{"answer":"G"},"r-18":{"answer":"A"},"r-19":{"answer":"B"},"r-20":{"answer":"E"},"r-21":{"answer":"B"},"r-22":{"answer":"B"},"r-23":{"answer":"C","explanation":"Dvigatel kutilganidan oson bo'lgan, haqiqiy muammo — ehtiyot qismlar."},"r-24":{"answer":"C"},"r-25":{"answer":"False"},"r-26":{"answer":"True"},"r-27":{"answer":"No Information"},"r-28":{"answer":"True"},"r-29":{"answer":"False","explanation":"Keyingi loyiha — mashina emas, eski mototsikl."},"r-30":{"answer":"nose"},"r-31":{"answer":"herds"},"r-32":{"answer":"disease"},"r-33":{"answer":"horns"},"r-34":{"answer":"B"},"r-35":{"answer":"A"}}$json$::jsonb, $json$[{"partId":"l1","lines":[{"voice":"narrator","text":"Part one. You will hear some sentences. Choose the correct reply to each sentence."},{"voice":"man","text":"Excuse me, can I pay by card here?","question":1},{"voice":"woman","text":"Have you seen my keys anywhere? I can't find them.","question":2},{"voice":"man","text":"Shall I book a table at the restaurant for tonight?","question":3},{"voice":"woman","text":"I'm afraid I can't come to your party on Saturday.","question":4},{"voice":"man","text":"Excuse me, does this train stop at Bukhara?","question":5},{"voice":"woman","text":"How about going for a walk after lunch?","question":6},{"voice":"man","text":"Ouch! I've just cut my finger!","question":7},{"voice":"woman","text":"What do you think of the new English teacher?","question":8},{"voice":"narrator","text":"That is the end of part one."}]},{"partId":"l2","lines":[{"voice":"narrator","text":"Part two. You will hear a camp director talking to parents. Fill in the missing information. Write one word and, or, a number for each answer."},{"voice":"man","text":"Good evening, everyone. Thank you for coming. I'd like to tell you about this year's Summer Language Camp."},{"voice":"man","text":"Please remember that registration closes on the first of July. The camp itself starts on the fifteenth of July and lasts for three weeks.","question":9},{"voice":"man","text":"The students stay in our new building. The rooms are quite large, and each room is for three students, with its own bathroom.","question":10},{"voice":"man","text":"There's an indoor pool, and the children can swim every afternoon. For hygiene reasons, everyone must bring a swimming cap. Towels are provided.","question":11},{"voice":"man","text":"Every Saturday we go on a trip. This year, instead of visiting the city museum, we'll go on a walk in the mountains to a beautiful waterfall.","question":12},{"voice":"man","text":"We want the children to speak English with each other, so phones are only allowed in the evening, after dinner, to call home.","question":13},{"voice":"man","text":"The price includes all lessons, meals, trips and books. The only thing it doesn't include is insurance, which you need to arrange yourselves.","question":14},{"voice":"narrator","text":"That is the end of part two."}]},{"partId":"l3","lines":[{"voice":"narrator","text":"Part three. You will hear people speaking in different situations. Match each speaker to the place where the speaker is. There are two extra places which you do not need to use."},{"voice":"narrator","text":"Speaker 1.","question":15},{"voice":"woman","text":"This jacket also comes in blue and black. What size are you, a medium? The fitting rooms are just over there, behind the shoes. Let me know if you need a different size."},{"voice":"narrator","text":"Speaker 2.","question":16},{"voice":"man","text":"Excuse me! Please don't run around the edge, it's very slippery. And if you can't swim well, stay in the shallow end. The lifeguard is always here if you need help."},{"voice":"narrator","text":"Speaker 3.","question":17},{"voice":"woman2","text":"So, just a little off the sides and the back, like last time? Let's wash it first, then I'll cut it. Would you like me to dry it straight or with some curls?"},{"voice":"narrator","text":"Speaker 4.","question":18},{"voice":"man2","text":"Fill it up, please, on pump number three. Oh, and could you check the air in my tyres? The front one looks a bit low. Do you take cards?"},{"voice":"narrator","text":"That is the end of part three."}]},{"partId":"l4","lines":[{"voice":"narrator","text":"Part four. You will hear someone giving a talk. Label the places on the map. There are three extra options which you do not need to use."},{"voice":"woman","text":"Welcome to the old town. We're standing next to the clock tower, on the north side of Bazaar Street. Let me tell you where to find a few interesting places."},{"voice":"woman","text":"If you'd like to buy a carpet, there's a wonderful carpet shop right next to the clock tower, on its west side, on this side of the street.","question":19},{"voice":"woman","text":"For tea, walk to the crossroads and turn into Mosque Road. Go north, and you'll find the tea house near the top of Mosque Road, on your left.","question":20},{"voice":"woman","text":"The pharmacy is on the corner of Bazaar Street and Mosque Road, on the east side of Mosque Road. Don't go further up the road, or you'll miss it.","question":21},{"voice":"woman","text":"The town museum is on Garden Street. Walk south down Garden Street, and it's right at the bottom, on your left-hand side.","question":22},{"voice":"woman","text":"And if you need a place to stay, the best hotel is on the south side of Bazaar Street, at the eastern end.","question":23},{"voice":"narrator","text":"That is the end of part four."}]},{"partId":"l5","lines":[{"voice":"narrator","text":"Part five. You will hear three extracts. Choose the correct answer for each question. There are two questions for each extract."},{"voice":"narrator","text":"Extract one. You will hear two students talking about a project."},{"voice":"woman","text":"Anvar, our teacher wants the project topic by Monday. Shall we do public transport?"},{"voice":"man","text":"Everyone's doing transport, Dilnoza. I think recycling is more interesting. We could visit the new recycling centre and take photos. Local history is too difficult to research in two weeks.","question":24},{"voice":"woman","text":"Fine, recycling it is. And for the presentation, I don't want to speak alone. Let's both present: you do the first half, and I'll do the second.","question":25},{"voice":"narrator","text":"Extract two. You will hear part of an interview with a marathon runner."},{"voice":"woman2","text":"Nigora, you've just finished your tenth marathon. Why did you start running?"},{"voice":"woman3","text":"Not to lose weight, as people often think. Five years ago I was in hospital for a month, and when I came out I felt so weak. My doctor said gentle exercise would help me get my strength back, so I started jogging.","question":26},{"voice":"woman3","text":"My advice to beginners? You don't need expensive shoes, and please don't run every day at first. The most important thing is to increase the distance slowly, a little more each week.","question":27},{"voice":"narrator","text":"Extract three. You will hear a conversation in a phone shop."},{"voice":"woman","text":"Hello, I bought this phone here two weeks ago. The screen's fine and I love the colour, but the battery runs out by lunchtime every day.","question":28},{"voice":"man2","text":"I'm sorry about that. As it's less than a month old, we won't repair it, and we can't give refunds on opened phones. But we'll exchange it for a new one right now.","question":29},{"voice":"narrator","text":"That is the end of part five."}]},{"partId":"l6","lines":[{"voice":"narrator","text":"Part six. You will hear a part of a lecture. Fill in the missing information. Write no more than one word for each answer."},{"voice":"man3","text":"Good morning. Today I'd like to talk about one of the most important insects on the planet: the honey bee."},{"voice":"man3","text":"A colony can contain tens of thousands of bees, but it has only one queen. Her job is to lay eggs, sometimes more than a thousand a day.","question":30},{"voice":"man3","text":"When a worker bee finds good flowers, she returns to the hive and performs a special dance. The direction and speed of the dance tell the other bees where the flowers are.","question":31},{"voice":"man3","text":"Honey is a remarkable food. Because it contains very little water, bacteria cannot grow in it, so it can stay good to eat for a very long time.","question":32},{"voice":"man3","text":"Bees also work together to control the climate of the hive. By fanning their wings or moving closer together, they keep it at a steady temperature.","question":33},{"voice":"man3","text":"Bees matter to us far more than honey. About a third of the food we eat depends on pollination by bees and other insects.","question":34},{"voice":"man3","text":"Sadly, bee numbers are falling in many countries. The main threats are disease and the pesticides that are used on farms.","question":35},{"voice":"narrator","text":"That is the end of part six."}]}]$json$::jsonb)
on conflict (test_id) do update set keys = excluded.keys, scripts = excluded.scripts;

