insert into public.test_keys (test_id, keys, scripts)
values ('t13', $json${"l-1":{"answer":"A"},"l-2":{"answer":"B"},"l-3":{"answer":"C"},"l-4":{"answer":"A"},"l-5":{"answer":"B","explanation":"\"Where\" — joy so'ralmoqda, vaqt emas."},"l-6":{"answer":"B"},"l-7":{"answer":"A"},"l-8":{"answer":"C"},"l-9":{"answer":"Wednesday"},"l-10":{"answer":"25|twenty-five","explanation":"O'tgan yili 30 dollar edi, endi 25."},"l-11":{"answer":"fortress"},"l-12":{"answer":"water"},"l-13":{"answer":"20|20th|twentieth"},"l-14":{"answer":"lens"},"l-15":{"answer":"E"},"l-16":{"answer":"B"},"l-17":{"answer":"F"},"l-18":{"answer":"D","explanation":"\"Next song\", \"sing along\" — konsert."},"l-19":{"answer":"F","explanation":"Rose Avenue dan sharqda, Lake Path ning janubiy tomonida. E esa g'arbda."},"l-20":{"answer":"H"},"l-21":{"answer":"A"},"l-22":{"answer":"B"},"l-23":{"answer":"D"},"l-24":{"answer":"A"},"l-25":{"answer":"A"},"l-26":{"answer":"A"},"l-27":{"answer":"B","explanation":"Chet elda o'qishni orzu qilgan, lekin hamma narsani onasidan o'rgangan."},"l-28":{"answer":"B"},"l-29":{"answer":"A"},"l-30":{"answer":"sand"},"l-31":{"answer":"furnace"},"l-32":{"answer":"Mesopotamia"},"l-33":{"answer":"cheaper"},"l-34":{"answer":"quality"},"l-35":{"answer":"energy"},"r-1":{"answer":"water"},"r-2":{"answer":"temperature"},"r-3":{"answer":"tired"},"r-4":{"answer":"glass"},"r-5":{"answer":"day"},"r-6":{"answer":"drinks"},"r-7":{"answer":"C"},"r-8":{"answer":"H"},"r-9":{"answer":"I"},"r-10":{"answer":"F"},"r-11":{"answer":"A"},"r-12":{"answer":"J"},"r-13":{"answer":"E"},"r-14":{"answer":"D"},"r-15":{"answer":"C"},"r-16":{"answer":"G"},"r-17":{"answer":"A","explanation":"H emas: paragraf zaryadlash muammosi haqida, benzin afzalligi haqida emas."},"r-18":{"answer":"F"},"r-19":{"answer":"E"},"r-20":{"answer":"B"},"r-21":{"answer":"B"},"r-22":{"answer":"C"},"r-23":{"answer":"C"},"r-24":{"answer":"B"},"r-25":{"answer":"True"},"r-26":{"answer":"True"},"r-27":{"answer":"No Information"},"r-28":{"answer":"False","explanation":"Matnda — amakivachchasining (cousin) to'yi."},"r-29":{"answer":"False"},"r-30":{"answer":"clay"},"r-31":{"answer":"1990"},"r-32":{"answer":"finished|completed"},"r-33":{"answer":"Khodja|Khoja"},"r-34":{"answer":"B"},"r-35":{"answer":"A"}}$json$::jsonb, $json$[{"partId":"l1","lines":[{"voice":"narrator","text":"Part one. You will hear some sentences. Choose the correct reply to each sentence."},{"voice":"man","text":"Is it OK if I leave a bit early today?","question":1},{"voice":"woman","text":"Excuse me, which bus goes to the airport?","question":2},{"voice":"man","text":"I've just found out — I've passed all my exams!","question":3},{"voice":"woman","text":"Could you turn the music down a bit, please?","question":4},{"voice":"man","text":"Where shall we meet tomorrow?","question":5},{"voice":"woman","text":"Would you like to try some of my plov?","question":6},{"voice":"man","text":"Excuse me, how much is this T-shirt?","question":7},{"voice":"woman","text":"I'm going to the shop. Do you need anything?","question":8},{"voice":"narrator","text":"That is the end of part one."}]},{"partId":"l2","lines":[{"voice":"narrator","text":"Part two. You will hear a club leader talking to new members. Fill in the missing information. Write one word and, or, a number for each answer."},{"voice":"man","text":"Hi, everyone, and welcome to the Photography Club. It's great to see so many new faces."},{"voice":"man","text":"We used to meet on Mondays, but most people found that difficult, so now our meetings are every Wednesday evening, from six to eight.","question":9},{"voice":"man","text":"Membership was thirty dollars a year until last summer, but we've managed to reduce it, so it now costs twenty-five dollars a year.","question":10},{"voice":"man","text":"Our first trip is next weekend. We're going to take photos of the old fortress outside the city. The light there is amazing in the late afternoon.","question":11},{"voice":"man","text":"Every spring we have a competition. Last year the theme was people, but this year's theme is water — rivers, rain, even a glass of tea.","question":12},{"voice":"man","text":"Please send your best three photos by the twentieth of March. We'll show the winners at the exhibition in April.","question":13},{"voice":"man","text":"And the prize? A local shop has kindly given us a new camera lens for the winner. Good luck, everyone!","question":14},{"voice":"narrator","text":"That is the end of part two."}]},{"partId":"l3","lines":[{"voice":"narrator","text":"Part three. You will hear people speaking in different situations. Match each speaker to the place where the speaker is. There are two extra places which you do not need to use."},{"voice":"narrator","text":"Speaker 1.","question":15},{"voice":"woman","text":"Ladies and gentlemen, we will be landing in about twenty minutes. Please return to your seats, fasten your seatbelts and make sure your table is folded away. The cabin crew will now collect any rubbish."},{"voice":"narrator","text":"Speaker 2.","question":16},{"voice":"man","text":"Good, two more sets of ten, and keep your back straight this time. Don't hold your breath. Remember to drink some water between exercises, and then we'll finish on the running machine."},{"voice":"narrator","text":"Speaker 3.","question":17},{"voice":"woman2","text":"Right, everyone, open your books at page forty. Today we're looking at the past tense. And please put last week's homework on my desk before you leave."},{"voice":"narrator","text":"Speaker 4.","question":18},{"voice":"man2","text":"Thank you, Tashkent! You've been amazing tonight. This next song is one you all know, so I want to hear you sing along with us!"},{"voice":"narrator","text":"That is the end of part three."}]},{"partId":"l4","lines":[{"voice":"narrator","text":"Part four. You will hear someone giving a talk. Label the places on the map. There are three extra options which you do not need to use."},{"voice":"woman","text":"Welcome to Green Hills Park. We're at the main gate, at the western end of Lake Path. Let me tell you where to find a few things."},{"voice":"woman","text":"The café is on the south side of Lake Path, just east of Rose Avenue. Don't confuse it with the building just before Rose Avenue, which is the staff office.","question":19},{"voice":"woman","text":"If you have children with you, the playground is down Rose Avenue. Walk all the way to the bottom, and it's on your right.","question":20},{"voice":"woman","text":"You can hire a boat right next to the lake. The boat hire is on the north side of Lake Path, just to the east of the water.","question":21},{"voice":"woman","text":"For maps and information, go along Lake Path and turn left into Hill Path. Walk north, and the information centre is near the top, on your right.","question":22},{"voice":"woman","text":"And the mini golf is very close to where we are now: on the south side of Lake Path, at the western end, near the gate.","question":23},{"voice":"narrator","text":"That is the end of part four."}]},{"partId":"l5","lines":[{"voice":"narrator","text":"Part five. You will hear three extracts. Choose the correct answer for each question. There are two questions for each extract."},{"voice":"narrator","text":"Extract one. You will hear two colleagues talking about a business trip."},{"voice":"man","text":"Lola, are the flights for Almaty booked? We're both speaking at the meeting on Thursday."},{"voice":"woman","text":"There's no need, I'm afraid. The client phoned this morning and cancelled the meeting. Their director has to be in Europe all week. The flights weren't even full.","question":24},{"voice":"woman","text":"They still want to see our plans, though, so we've agreed to have a video call on Thursday instead. I'll send the link this afternoon.","question":25},{"voice":"narrator","text":"Extract two. You will hear part of a radio interview with a chef."},{"voice":"woman2","text":"Davron, your restaurant is always full. What makes it different?"},{"voice":"man2","text":"We only cook with what's in season and grown nearby. In winter you won't find tomatoes on our menu. Our prices aren't the cheapest, but people taste the difference.","question":26},{"voice":"man2","text":"I always dreamed of going to a famous cooking school abroad, but I never did. Everything I know, I learnt from my mother, in her tiny kitchen.","question":27},{"voice":"narrator","text":"Extract three. You will hear a mother and her son talking about university."},{"voice":"man3","text":"Mum, I know you wanted me to study medicine, and Dad keeps talking about law. But I really want to study architecture. I love designing things.","question":28},{"voice":"woman","text":"Then that's what you should do. But before you decide, let's go to the university open day next month. You can talk to the students and see the department yourself.","question":29},{"voice":"narrator","text":"That is the end of part five."}]},{"partId":"l6","lines":[{"voice":"narrator","text":"Part six. You will hear a part of a lecture. Fill in the missing information. Write no more than one word for each answer."},{"voice":"man3","text":"Good afternoon. Today's topic is a material we look through every day: glass."},{"voice":"man3","text":"The main ingredient of glass is surprisingly simple: sand. It is mixed with a few other substances, such as soda and lime.","question":30},{"voice":"man3","text":"The mixture is then heated in a furnace to well over a thousand degrees, until it becomes a thick liquid.","question":31},{"voice":"man3","text":"People have been making glass for a very long time. The earliest glass objects, mostly beads, were made in Mesopotamia more than four thousand years ago.","question":32},{"voice":"man3","text":"About two thousand years ago, the technique of glass-blowing appeared. It made glass much cheaper, and glass cups and bottles became common.","question":33},{"voice":"man3","text":"One great thing about glass is that it can be recycled again and again without losing its quality.","question":34},{"voice":"man3","text":"Today, scientists are developing new kinds of glass. Modern windows, for example, use special glass that keeps heat inside in winter and helps buildings save energy.","question":35},{"voice":"narrator","text":"That is the end of part six."}]}]$json$::jsonb)
on conflict (test_id) do update set keys = excluded.keys, scripts = excluded.scripts;

insert into public.tests (id, number, title, format_month, format_year, is_new, is_free, is_pro, content)
values ('t14', 14, 'Mock Test #14', 9, 2026, false, false, true, $json${"sections":[{"kind":"listening","title":"Listening","parts":6,"questions":35,"minutes":35},{"kind":"reading","title":"Reading","parts":5,"questions":35,"minutes":60},{"kind":"writing","title":"Writing","parts":2,"minutes":60},{"kind":"speaking","title":"Speaking","parts":3,"minutes":15,"approx":true}],"listening":[{"id":"l1","index":1,"instruction":"You will hear some sentences. Choose the correct reply to each sentence.","emphasis":"A, B or C","durationSec":47,"questions":[{"id":"l-1","number":1,"kind":"mcq","prompt":"","options":[{"key":"A","text":"It's at three o'clock."},{"key":"B","text":"Yes, it's on the second floor."},{"key":"C","text":"I don't have a meeting."}]},{"id":"l-2","number":2,"kind":"mcq","prompt":"","options":[{"key":"A","text":"That's very kind of you, thanks."},{"key":"B","text":"They're new bags."},{"key":"C","text":"I can help you too."}]},{"id":"l-3","number":3,"kind":"mcq","prompt":"","options":[{"key":"A","text":"Nice to meet you too."},{"key":"B","text":"I'll catch it."},{"key":"C","text":"It's Bobur. B-O-B-U-R."}]},{"id":"l-4","number":4,"kind":"mcq","prompt":"","options":[{"key":"A","text":"About three times a week."},{"key":"B","text":"For an hour."},{"key":"C","text":"With my brother."}]},{"id":"l-5","number":5,"kind":"mcq","prompt":"","options":[{"key":"A","text":"It was very tasty."},{"key":"B","text":"Good idea, I'm too tired to cook."},{"key":"C","text":"I ordered it yesterday."}]},{"id":"l-6","number":6,"kind":"mcq","prompt":"","options":[{"key":"A","text":"Not really, it was too long."},{"key":"B","text":"Yes, I'll enjoy it."},{"key":"C","text":"It starts at eight."}]},{"id":"l-7","number":7,"kind":"mcq","prompt":"","options":[{"key":"A","text":"I lent it on Friday."},{"key":"B","text":"Sorry, I'm a bit short myself."},{"key":"C","text":"It's a lot of money."}]},{"id":"l-8","number":8,"kind":"mcq","prompt":"","options":[{"key":"A","text":"Thanks, I'll be careful."},{"key":"B","text":"I'll watch it later."},{"key":"C","text":"It's raining outside."}]}],"audio":"t14/l1.mp3","audioAt":{"1":7,"2":12,"3":18,"4":23,"5":27,"6":31,"7":35,"8":39}},{"id":"l2","index":2,"title":"Day trip to Shahrisabz","instruction":"You will hear a tour guide talking to a group. Fill in the missing information. Write","emphasis":"ONE WORD and / or A NUMBER","durationSec":70,"questions":[{"id":"l-9","number":9,"kind":"gap","prompt":"The bus leaves at … o’clock"},{"id":"l-10","number":10,"kind":"gap","prompt":"The journey takes about … hours"},{"id":"l-11","number":11,"kind":"gap","prompt":"First stop: the ruins of the … Palace"},{"id":"l-12","number":12,"kind":"gap","prompt":"Lunch: in a local family"},{"id":"l-13","number":13,"kind":"gap","prompt":"Bring a … because of the sun"},{"id":"l-14","number":14,"kind":"gap","prompt":"Return to Samarkand by … pm"}],"audio":"t14/l2.mp3","audioAt":{"9":20,"10":28,"11":37,"12":46,"13":52,"14":60}},{"id":"l3","index":3,"instruction":"You will hear people speaking in different situations. Match each speaker (15–18) to the place where the speaker is (A–F). There are","emphasis":"TWO EXTRA places","durationSec":66,"choices":[{"key":"A","text":"at a post office"},{"key":"B","text":"at a cinema"},{"key":"C","text":"at a hotel"},{"key":"D","text":"at a train station"},{"key":"E","text":"in a bookshop"},{"key":"F","text":"at a car repair garage"}],"questions":[{"id":"l-15","number":15,"kind":"match","prompt":"Speaker 1"},{"id":"l-16","number":16,"kind":"match","prompt":"Speaker 2"},{"id":"l-17","number":17,"kind":"match","prompt":"Speaker 3"},{"id":"l-18","number":18,"kind":"match","prompt":"Speaker 4"}],"audio":"t14/l3.mp3","audioAt":{"15":15,"16":28,"17":40,"18":52}},{"id":"l4","index":4,"instruction":"You will hear someone giving a talk. Label the places (19–23) on the map (A–H). There are","emphasis":"THREE extra options","durationSec":72,"choices":[{"key":"A","text":""},{"key":"B","text":""},{"key":"C","text":""},{"key":"D","text":""},{"key":"E","text":""},{"key":"F","text":""},{"key":"G","text":""},{"key":"H","text":""}],"map":{"width":320,"height":240,"roads":[{"points":[[10,125],[310,125]]},{"points":[[120,10],[120,125]]},{"points":[[230,125],[230,230]]}],"blocks":[{"x":20,"y":78,"w":55,"h":32,"letter":"A"},{"x":134,"y":78,"w":55,"h":32,"letter":"B"},{"x":50,"y":22,"w":55,"h":32,"letter":"C"},{"x":134,"y":22,"w":55,"h":32,"letter":"D"},{"x":250,"y":78,"w":55,"h":32,"letter":"E"},{"x":20,"y":140,"w":55,"h":32,"letter":"F"},{"x":128,"y":140,"w":80,"h":34,"name":"Station"},{"x":246,"y":150,"w":55,"h":32,"letter":"G"},{"x":140,"y":192,"w":60,"h":32,"letter":"H"}],"labels":[{"x":60,"y":129,"text":"Station Road"},{"x":120,"y":20,"text":"Market Street"},{"x":230,"y":236,"text":"Canal Road"}]},"questions":[{"id":"l-19","number":19,"kind":"match","prompt":"Bike hire"},{"id":"l-20","number":20,"kind":"match","prompt":"Hotel"},{"id":"l-21","number":21,"kind":"match","prompt":"Police station"},{"id":"l-22","number":22,"kind":"match","prompt":"Supermarket"},{"id":"l-23","number":23,"kind":"match","prompt":"Car park"}],"audio":"t14/l4.mp3","audioAt":{"19":23,"20":33,"21":41,"22":53,"23":62}},{"id":"l5","index":5,"instruction":"You will hear three extracts. Choose the correct answer (A, B or C) for each question. There are","emphasis":"TWO questions for each extract","durationSec":93,"questions":[{"id":"l-24","number":24,"kind":"mcq","prompt":"What is the main problem in the flat?","options":[{"key":"A","text":"The kitchen is always dirty."},{"key":"B","text":"The neighbours are noisy."},{"key":"C","text":"The rent is too high."}],"group":"Extract One"},{"id":"l-25","number":25,"kind":"mcq","prompt":"What do the flatmates decide to do?","options":[{"key":"A","text":"pay for a cleaner"},{"key":"B","text":"make a cleaning timetable"},{"key":"C","text":"eat out more often"}],"group":"Extract One"},{"id":"l-26","number":26,"kind":"mcq","prompt":"According to the rescuer, why do most people need help?","options":[{"key":"A","text":"bad weather"},{"key":"B","text":"getting lost"},{"key":"C","text":"serious injuries"}],"group":"Extract Two"},{"id":"l-27","number":27,"kind":"mcq","prompt":"What is his most important advice?","options":[{"key":"A","text":"Always tell someone your route."},{"key":"B","text":"Never walk alone."},{"key":"C","text":"Carry extra food."}],"group":"Extract Two"},{"id":"l-28","number":28,"kind":"mcq","prompt":"What does the customer want to change?","options":[{"key":"A","text":"the dates of her trip"},{"key":"B","text":"her destination"},{"key":"C","text":"her hotel"}],"group":"Extract Three"},{"id":"l-29","number":29,"kind":"mcq","prompt":"How much will the change cost?","options":[{"key":"A","text":"nothing"},{"key":"B","text":"20 dollars"},{"key":"C","text":"50 dollars"}],"group":"Extract Three"}],"audio":"t14/l5.mp3","audioAt":{"24":15,"25":25,"26":46,"27":59,"28":72,"29":82}},{"id":"l6","index":6,"title":"The camel","instruction":"You will hear a part of a lecture. Fill in the missing information. Write","emphasis":"no more than ONE WORD","durationSec":70,"questions":[{"id":"l-30","number":30,"kind":"gap","prompt":"A camel’s hump stores"},{"id":"l-31","number":31,"kind":"gap","prompt":"Camels can close their … to keep out sand"},{"id":"l-32","number":32,"kind":"gap","prompt":"Camels with two humps are called"},{"id":"l-33","number":33,"kind":"gap","prompt":"A thirsty camel can drink a lot of water very"},{"id":"l-34","number":34,"kind":"gap","prompt":"Camel milk is rich in vitamin C and"},{"id":"l-35","number":35,"kind":"gap","prompt":"In Central Asia, camels were essential for"}],"audio":"t14/l6.mp3","audioAt":{"30":17,"31":26,"32":33,"33":41,"34":48,"35":57}}],"reading":[{"id":"r1","index":1,"title":"Why volunteer?","instruction":"Read the text. Fill in each gap with ONE word. You must use a word which is somewhere in the rest of the text.","passage":[{"label":"1","text":"Volunteering means giving your time to help others without being paid. Many (1) ______ believe they are too busy to volunteer, but even a few hours a month can make a difference. You can visit older (2) ______, clean parks or teach children to read."},{"label":"2","text":"Volunteering is good for the community, but it is also good for the (3) ______ themselves. Studies show that people who help others feel happier and less lonely. Young people can also gain useful (4) ______ such as teamwork and organisation. To find an opportunity, ask at your local (5) ______ or search online. Choose something you enjoy, so that you will want to (6) ______."},{"label":"3","text":"Volunteers often say they get more than they give. Many people who are busy still find time, and even helping your neighbours with their shopping counts. Young volunteers learn new skills, and the local library usually has a list of projects. Once you start, you will want to return again and again."}],"questions":[{"id":"r-1","number":1,"kind":"gap","prompt":"Many (1) ______ believe they are too busy to volunteer."},{"id":"r-2","number":2,"kind":"gap","prompt":"You can visit older (2) ______."},{"id":"r-3","number":3,"kind":"gap","prompt":"It is also good for the (3) ______ themselves."},{"id":"r-4","number":4,"kind":"gap","prompt":"Young people can gain useful (4) ______."},{"id":"r-5","number":5,"kind":"gap","prompt":"Ask at your local (5) ______."},{"id":"r-6","number":6,"kind":"gap","prompt":"Choose something you enjoy, so that you will want to (6) ______."}]},{"id":"r2","index":2,"title":"Places to stay","instruction":"Read the texts 7–14 and the statements A–J. Decide which text matches the situation in each statement. Each statement can be used ONCE only. There are TWO extra statements.","passage":[{"label":"7","text":"MOUNTAIN CABIN — Sleeps up to eight people. A large living room with a fireplace — perfect for big groups of friends."},{"label":"8","text":"CITY STUDIO — Next to the metro, with a desk and fast wi-fi. Ideal for business travellers who need to work."},{"label":"9","text":"LAKESIDE CAMPSITE — Bring your own tent. Showers and a small shop. Pets are welcome."},{"label":"10","text":"FARM STAY — Help us feed the cows and goats, and enjoy fresh milk and eggs every morning."},{"label":"11","text":"OLD TOWN B&B — Stay in a beautiful 200-year-old merchant’s house. Free walking tour for all guests."},{"label":"12","text":"BEACH HOTEL — Breakfast, lunch and dinner are all included in the price. Three swimming pools."},{"label":"13","text":"STUDENT HOSTEL — Beds from just $8 a night. Shared kitchen and lounge. The best prices in town."},{"label":"14","text":"GARDEN APARTMENT — Ground floor, wide doors and a step-free bathroom, suitable for wheelchair users."}],"choices":[{"key":"A","text":"You do not want to pay for meals separately."},{"key":"B","text":"You would like to help look after animals."},{"key":"C","text":"You want the cheapest possible place to stay."},{"key":"D","text":"You want to go skiing."},{"key":"E","text":"You need to work during your stay."},{"key":"F","text":"One person in your group uses a wheelchair."},{"key":"G","text":"You want a room with a sea view."},{"key":"H","text":"You are travelling in a large group."},{"key":"I","text":"You want to bring your dog."},{"key":"J","text":"You want to stay in a historic building."}],"questions":[{"id":"r-7","number":7,"kind":"match","prompt":"Text 7"},{"id":"r-8","number":8,"kind":"match","prompt":"Text 8"},{"id":"r-9","number":9,"kind":"match","prompt":"Text 9"},{"id":"r-10","number":10,"kind":"match","prompt":"Text 10"},{"id":"r-11","number":11,"kind":"match","prompt":"Text 11"},{"id":"r-12","number":12,"kind":"match","prompt":"Text 12"},{"id":"r-13","number":13,"kind":"match","prompt":"Text 13"},{"id":"r-14","number":14,"kind":"match","prompt":"Text 14"}]},{"id":"r3","index":3,"title":"Growing up online","instruction":"Read the text and choose the correct heading for each paragraph from the list of headings. There are more headings than paragraphs, so you will not use all of them.","passage":[{"label":"I","text":"For today’s teenagers, the internet is not a place they visit; it is where they live. Many check their phones dozens of times a day, and messages from friends arrive from the moment they wake up until long after they should be asleep."},{"label":"II","text":"This is not all bad news. Social media allows young people to stay in touch with friends who have moved away and to find others who share their interests. Teenagers who feel different at school can often find a community online where they are accepted."},{"label":"III","text":"However, many young people say they feel they must always look their best. Photos are carefully chosen and edited, so it is easy to believe that everyone else has a more exciting and beautiful life. This constant comparison can damage confidence."},{"label":"IV","text":"Doctors are also worried about sleep. The light from screens tells the brain that it is still daytime, and exciting messages keep teenagers awake. As a result, many arrive at school tired and find it hard to concentrate in the morning."},{"label":"V","text":"Parents have an important role. Experts suggest agreeing on simple rules, such as no phones at the dinner table or in the bedroom at night. But they also say that children copy what adults do, so parents should think about their own screen habits too."},{"label":"VI","text":"Schools are starting to help as well. In some countries, students now have lessons on how to recognise false information, protect their privacy and behave kindly online — skills that are just as important today as reading and writing."}],"choices":[{"key":"A","text":"Late nights, tired mornings"},{"key":"B","text":"Lessons for the digital age"},{"key":"C","text":"Always connected"},{"key":"D","text":"Why teenagers prefer games"},{"key":"E","text":"The pressure to look perfect"},{"key":"F","text":"Setting a good example"},{"key":"G","text":"A place to belong"},{"key":"H","text":"Banning phones completely"}],"questions":[{"id":"r-15","number":15,"kind":"match","prompt":"Paragraph I"},{"id":"r-16","number":16,"kind":"match","prompt":"Paragraph II"},{"id":"r-17","number":17,"kind":"match","prompt":"Paragraph III"},{"id":"r-18","number":18,"kind":"match","prompt":"Paragraph IV"},{"id":"r-19","number":19,"kind":"match","prompt":"Paragraph V"},{"id":"r-20","number":20,"kind":"match","prompt":"Paragraph VI"}]},{"id":"r4","index":4,"title":"Learning to swim at forty","instruction":"Read the text. For questions 21–24, choose the correct answer A, B, C or D. For questions 25–29, decide if the statements agree with the information in the text.","passage":[{"label":"1","text":"I grew up in a small town in the desert, far from any river or lake, and nobody in my family could swim. As an adult I always found excuses to stay out of the water. On beach holidays I sat under an umbrella and told everyone I preferred reading."},{"label":"2","text":"Everything changed two years ago, when I watched my nine-year-old daughter in her first swimming race. She came last, but she climbed out of the pool smiling and asked me why I never swam with her. I did not have a good answer. The next week, at the age of forty, I signed up for lessons."},{"label":"3","text":"The lessons were at six in the morning, before work. The water was not cold and the pool was almost empty, but I was terrified of putting my face under the water. For the first three weeks I could not do it at all, and I almost gave up."},{"label":"4","text":"My instructor, a calm young man called Timur, was endlessly patient. He never laughed and never made me feel stupid. Instead, he broke everything into tiny steps: first breathing out through my nose, then counting to three under the water, then to five."},{"label":"5","text":"Last summer, I swam in the sea for the first time, next to my daughter. It was only a few hundred metres, and it was not elegant, but I did not care. I am not ready to teach anyone, but I tell every adult who cannot swim the same thing: it is never too late."}],"questions":[{"id":"r-21","number":21,"kind":"mcq","prompt":"Why had the writer never learnt to swim?","options":[{"key":"A","text":"She did not like water."},{"key":"B","text":"She was always too busy."},{"key":"C","text":"She grew up far from water and nobody taught her."},{"key":"D","text":"She had a bad experience as a child."}]},{"id":"r-22","number":22,"kind":"mcq","prompt":"What made the writer decide to take lessons?","options":[{"key":"A","text":"advice from her doctor"},{"key":"B","text":"a question from her daughter"},{"key":"C","text":"a beach holiday"},{"key":"D","text":"a friend at work"}]},{"id":"r-23","number":23,"kind":"mcq","prompt":"The first lessons were difficult because she","options":[{"key":"A","text":"was afraid of putting her face in the water."},{"key":"B","text":"found the water too cold."},{"key":"C","text":"did not like her instructor."},{"key":"D","text":"had to share the pool with many people."}]},{"id":"r-24","number":24,"kind":"mcq","prompt":"What does the writer say about her instructor?","options":[{"key":"A","text":"He was very strict."},{"key":"B","text":"He often laughed at her."},{"key":"C","text":"He was patient and explained things step by step."},{"key":"D","text":"He was an old friend of hers."}]},{"id":"r-25","number":25,"kind":"tfng","prompt":"The writer lived near a river as a child."},{"id":"r-26","number":26,"kind":"tfng","prompt":"The writer’s husband can swim."},{"id":"r-27","number":27,"kind":"tfng","prompt":"The lessons took place early in the morning."},{"id":"r-28","number":28,"kind":"tfng","prompt":"The writer swam in the sea last summer."},{"id":"r-29","number":29,"kind":"tfng","prompt":"The writer now teaches swimming to adults."}]},{"id":"r5","index":5,"title":"The journey of the tulip","instruction":"Read the text. For questions 30–33, fill in the missing information. Write no more than ONE WORD and / or A NUMBER. For questions 34–35, choose the correct answer A, B, C or D.","passage":[{"label":"1","text":"Most people connect tulips with the Netherlands, but the flower’s real home is much further east. Wild tulips first grew on the mountain slopes of Central Asia, and many species can still be found in Uzbekistan every spring."},{"label":"2","text":"Tulips were grown in the gardens of the Ottoman Empire, and in the sixteenth century they arrived in the Netherlands. There, they quickly became a symbol of wealth. In the 1630s, during a period later called “tulip mania”, prices rose so high that a single rare bulb was said to cost as much as a house."},{"label":"3","text":"Central Asia’s wild tulips are just as remarkable as the famous garden varieties. Greig’s tulip, for example, has bright red flowers and unusual striped leaves, and it has been used to create many modern garden tulips."},{"label":"4","text":"Today, however, many wild tulips are in danger. People dig up the bulbs to sell them, and grazing animals and new roads destroy the places where they grow. Botanists are now working to protect the remaining populations, so that these ancestors of the world’s favourite spring flower do not disappear."}],"questions":[{"id":"r-30","number":30,"kind":"gap","prompt":"Wild tulips first grew in the mountains of Central"},{"id":"r-31","number":31,"kind":"gap","prompt":"In the sixteenth century, tulips arrived in the"},{"id":"r-32","number":32,"kind":"gap","prompt":"During “tulip mania”, one bulb could cost as much as a"},{"id":"r-33","number":33,"kind":"gap","prompt":"Greig’s tulip has striped"},{"id":"r-34","number":34,"kind":"mcq","prompt":"Why are wild tulips in danger today?","options":[{"key":"A","text":"The climate is becoming too dry."},{"key":"B","text":"People dig up the bulbs and their habitats are destroyed."},{"key":"C","text":"Gardeners prefer modern varieties."},{"key":"D","text":"They no longer produce seeds."}]},{"id":"r-35","number":35,"kind":"mcq","prompt":"What is the writer’s main purpose?","options":[{"key":"A","text":"to give advice on growing tulips"},{"key":"B","text":"to explain the history of tulips from Central Asia to Europe"},{"key":"C","text":"to describe the economy of the Netherlands"},{"key":"D","text":"to compare tulips with other spring flowers"}]}]}],"writing":[{"id":"w1","index":1,"label":"Task 1","kind":"Letter","context":"You are a student living in a university dormitory, and you have been having problems with your room.","prompt":"Write an email to the dormitory manager. In your email:\n- describe the problems;\n- explain how they affect your studies;\n- say what you would like the manager to do.\nWrite about 150 words in an appropriate format and style.","targetWords":150,"minWords":120,"weight":1},{"id":"w2","index":2,"label":"Task 2","kind":"Essay","prompt":"Some people believe that unpaid community work should be a compulsory part of high school education. Others think it should be the student’s own choice.\n\nDiscuss both views and give your opinion. Write at least 250 words in an appropriate style and format.","targetWords":250,"minWords":250,"weight":2}],"speaking":[{"id":"s1","index":1,"part":"1.1","prompt":"What do you like about the place where you live?","prepSec":5,"answerSec":30},{"id":"s2","index":2,"part":"1.1","prompt":"How do you usually celebrate your birthday?","prepSec":5,"answerSec":30},{"id":"s3","index":3,"part":"1.1","prompt":"Do you like reading? What do you read?","prepSec":5,"answerSec":30},{"id":"s4","index":4,"part":"1.2","prompt":"Compare the two pictures. What are the similarities and differences?","image":"Picture A: a family on holiday at the beach · Picture B: a group of friends hiking in the mountains","prepSec":10,"answerSec":45},{"id":"s5","index":5,"part":"1.2","prompt":"Which holiday would you prefer? Why?","image":"Picture A: a family on holiday at the beach · Picture B: a group of friends hiking in the mountains","prepSec":5,"answerSec":30},{"id":"s6","index":6,"part":"1.2","prompt":"Why do people need holidays?","image":"Picture A: a family on holiday at the beach · Picture B: a group of friends hiking in the mountains","prepSec":5,"answerSec":30},{"id":"s7","index":7,"part":"2","prompt":"Describe a difficult challenge you have faced. Say what the challenge was, how you dealt with it and what you learned from it.","image":"A student giving a presentation in front of a class","prepSec":60,"answerSec":120},{"id":"s8","index":8,"part":"3","prompt":"Children should start learning a foreign language in kindergarten. For: young children learn languages easily and naturally. Against: they should first master their own language. Give arguments for and against this statement and say what you think.","prepSec":60,"answerSec":120}]}$json$::jsonb)
