values ('t14', $json${"l-1":{"answer":"B"},"l-2":{"answer":"A"},"l-3":{"answer":"C"},"l-4":{"answer":"A","explanation":"\"How often\" — chastota so'raladi."},"l-5":{"answer":"B"},"l-6":{"answer":"A"},"l-7":{"answer":"B"},"l-8":{"answer":"A"},"l-9":{"answer":"7|seven"},"l-10":{"answer":"2|two","explanation":"O'tgan yili yo'l ta'miri tufayli 3 soat bo'lgan, hozir 2 soat."},"l-11":{"answer":"White"},"l-12":{"answer":"home|house"},"l-13":{"answer":"hat"},"l-14":{"answer":"8|eight"},"l-15":{"answer":"A"},"l-16":{"answer":"E"},"l-17":{"answer":"F"},"l-18":{"answer":"B","explanation":"Poyezd haqida gap bor, lekin chipta va qator — kinoteatr."},"l-19":{"answer":"B"},"l-20":{"answer":"C"},"l-21":{"answer":"G"},"l-22":{"answer":"F"},"l-23":{"answer":"H"},"l-24":{"answer":"A"},"l-25":{"answer":"B","explanation":"Farrosh yollash qimmat deb rad etiladi."},"l-26":{"answer":"B"},"l-27":{"answer":"A"},"l-28":{"answer":"A"},"l-29":{"answer":"A","explanation":"50 dollar — 30 kundan keyin o'zgartirilsa. Bu safar bepul."},"l-30":{"answer":"fat"},"l-31":{"answer":"nostrils"},"l-32":{"answer":"Bactrian"},"l-33":{"answer":"quickly|fast"},"l-34":{"answer":"iron"},"l-35":{"answer":"trade"},"r-1":{"answer":"people"},"r-2":{"answer":"neighbours|neighbors"},"r-3":{"answer":"volunteers"},"r-4":{"answer":"skills"},"r-5":{"answer":"library"},"r-6":{"answer":"return"},"r-7":{"answer":"H"},"r-8":{"answer":"E"},"r-9":{"answer":"I"},"r-10":{"answer":"B"},"r-11":{"answer":"J"},"r-12":{"answer":"A","explanation":"Dengiz manzarasi (G) haqida matnda hech narsa yo'q."},"r-13":{"answer":"C"},"r-14":{"answer":"F"},"r-15":{"answer":"C"},"r-16":{"answer":"G"},"r-17":{"answer":"E"},"r-18":{"answer":"A"},"r-19":{"answer":"F","explanation":"H emas: telefonni butunlay taqiqlash emas, oddiy qoidalar va o'rnak haqida."},"r-20":{"answer":"B"},"r-21":{"answer":"C"},"r-22":{"answer":"B"},"r-23":{"answer":"A"},"r-24":{"answer":"C"},"r-25":{"answer":"False"},"r-26":{"answer":"No Information"},"r-27":{"answer":"True"},"r-28":{"answer":"True"},"r-29":{"answer":"False"},"r-30":{"answer":"Asia"},"r-31":{"answer":"Netherlands"},"r-32":{"answer":"house"},"r-33":{"answer":"leaves"},"r-34":{"answer":"B"},"r-35":{"answer":"B"}}$json$::jsonb, $json$[{"partId":"l1","lines":[{"voice":"narrator","text":"Part one. You will hear some sentences. Choose the correct reply to each sentence."},{"voice":"woman","text":"Excuse me, do you know where the meeting room is?","question":1},{"voice":"man","text":"Those look heavy. Can I help you with your bags?","question":2},{"voice":"woman","text":"I'm sorry, I didn't catch your name.","question":3},{"voice":"man","text":"How often do you go to the gym?","question":4},{"voice":"woman","text":"Let's order a pizza tonight.","question":5},{"voice":"man","text":"So, did you enjoy the film?","question":6},{"voice":"woman","text":"Could you lend me some money until Friday?","question":7},{"voice":"man","text":"Watch out! The floor's wet.","question":8},{"voice":"narrator","text":"That is the end of part one."}]},{"partId":"l2","lines":[{"voice":"narrator","text":"Part two. You will hear a tour guide talking to a group. Fill in the missing information. Write one word and, or, a number for each answer."},{"voice":"woman","text":"Good evening, everyone. Tomorrow we're going on a day trip to Shahrisabz, the birthplace of Amir Timur. Here's what you need to know."},{"voice":"woman","text":"Please be in the hotel lobby on time, because the bus leaves at seven o'clock sharp. Breakfast will be ready from six.","question":9},{"voice":"woman","text":"Last year, because of road works, the journey took three hours, but the new road is open now, so it takes about two hours.","question":10},{"voice":"woman","text":"Our first stop is the ruins of the White Palace, or Ak-Saray. Only part of the huge entrance gate is still standing, but it's very impressive.","question":11},{"voice":"woman","text":"For lunch, we won't go to a restaurant. Instead, we'll eat in a local family home, where you can try homemade dishes.","question":12},{"voice":"woman","text":"It will be very sunny tomorrow, and there's little shade, so please bring a hat. We'll provide water on the bus.","question":13},{"voice":"woman","text":"We'll leave Shahrisabz at about six, and we should be back in Samarkand by eight p.m. See you in the morning!","question":14},{"voice":"narrator","text":"That is the end of part two."}]},{"partId":"l3","lines":[{"voice":"narrator","text":"Part three. You will hear people speaking in different situations. Match each speaker to the place where the speaker is. There are two extra places which you do not need to use."},{"voice":"narrator","text":"Speaker 1.","question":15},{"voice":"man","text":"I'd like to send this parcel to Germany, please. Could you weigh it? And I need ten stamps for postcards as well. How long will the parcel take to arrive?"},{"voice":"narrator","text":"Speaker 2.","question":16},{"voice":"woman","text":"Hello, I'm looking for a novel by Abdulla Qodiriy for my sister. Is it in the classics section, or should I look with the new bestsellers? A gift bag would be great, too."},{"voice":"narrator","text":"Speaker 3.","question":17},{"voice":"man2","text":"I've had a look under the car. The brakes need changing, and one tyre is quite old. We'll order the parts today, and it should be ready tomorrow afternoon."},{"voice":"narrator","text":"Speaker 4.","question":18},{"voice":"woman2","text":"Two tickets for the seven o'clock showing of 'The Last Train', please. Row seven, if possible, in the middle. And a large popcorn to share."},{"voice":"narrator","text":"That is the end of part three."}]},{"partId":"l4","lines":[{"voice":"narrator","text":"Part four. You will hear someone giving a talk. Label the places on the map. There are three extra options which you do not need to use."},{"voice":"man","text":"Welcome. We're standing outside the station entrance, on the south side of Station Road. Let me explain where a few useful places are."},{"voice":"man","text":"You can hire a bike directly across Station Road from here, on the corner with Market Street, on the east side of Market Street.","question":19},{"voice":"man","text":"Your hotel is on Market Street. Walk north up Market Street, and you'll find it near the top, on your left.","question":20},{"voice":"man","text":"If you lose anything, the police station is on Canal Road. Go east along Station Road, turn right into Canal Road, and it's on your left.","question":21},{"voice":"man","text":"For food shopping, the supermarket is at the far western end of Station Road, on this side, the south side.","question":22},{"voice":"man","text":"And if you come by car, the car park is directly behind the station.","question":23},{"voice":"narrator","text":"That is the end of part four."}]},{"partId":"l5","lines":[{"voice":"narrator","text":"Part five. You will hear three extracts. Choose the correct answer for each question. There are two questions for each extract."},{"voice":"narrator","text":"Extract one. You will hear two flatmates talking."},{"voice":"woman","text":"Jamshid, we need to talk. The neighbours are fine and the rent's OK, but the kitchen is a mess every single day. I'm tired of washing everyone's plates.","question":24},{"voice":"man","text":"You're right, sorry. Paying for a cleaner would be too expensive, though. Why don't we make a timetable, so everyone cleans on different days?","question":25},{"voice":"narrator","text":"Extract two. You will hear part of an interview with a mountain rescuer."},{"voice":"woman2","text":"Alisher, you rescue walkers in the mountains. Why do most people need your help?"},{"voice":"man2","text":"People imagine it's always storms or broken legs. Those happen, but most of our calls are simply people who've got lost. They leave the path and can't find it again.","question":26},{"voice":"man2","text":"My most important advice: always tell someone your route and when you'll be back. Walking alone isn't a problem if somebody knows where you are.","question":27},{"voice":"narrator","text":"Extract three. You will hear a conversation in a travel agency."},{"voice":"woman3","text":"Hello, I booked a trip to Istanbul with you last week. I still want to go to the same hotel, but my sister's wedding has moved, so I need to change the dates.","question":28},{"voice":"man3","text":"That's no problem. Changes within thirty days of booking are free, so there's nothing to pay. After that it would be fifty dollars.","question":29},{"voice":"narrator","text":"That is the end of part five."}]},{"partId":"l6","lines":[{"voice":"narrator","text":"Part six. You will hear a part of a lecture. Fill in the missing information. Write no more than one word for each answer."},{"voice":"man3","text":"Today's lecture is about an animal that has been part of life in Central Asia for thousands of years: the camel."},{"voice":"man3","text":"Many people believe a camel's hump is full of water. In fact, it stores fat, which the camel can use for energy when food is hard to find.","question":30},{"voice":"man3","text":"Camels are perfectly suited to the desert. They have long eyelashes, and they can close their nostrils to keep out sand during storms.","question":31},{"voice":"man3","text":"There are two main kinds. Camels with one hump are called dromedaries, and camels with two humps are called Bactrian camels.","question":32},{"voice":"man3","text":"Camels can go for days without drinking. But when a thirsty camel finds water, it can drink an enormous amount very quickly.","question":33},{"voice":"man3","text":"Camel milk is also important. It is rich in vitamin C and iron, and in many desert regions it is a key part of people's diet.","question":34},{"voice":"man3","text":"Finally, history. For centuries, camel caravans carried goods across the deserts, and in Central Asia camels were essential for trade along the Silk Road.","question":35},{"voice":"narrator","text":"That is the end of part six."}]}]$json$::jsonb)
on conflict (test_id) do update set keys = excluded.keys, scripts = excluded.scripts;

insert into public.tests (id, number, title, format_month, format_year, is_new, is_free, is_pro, content)
values ('t15', 15, 'Mock Test #15', 9, 2026, true, false, true, $json${"sections":[{"kind":"listening","title":"Listening","parts":6,"questions":35,"minutes":35},{"kind":"reading","title":"Reading","parts":5,"questions":35,"minutes":60},{"kind":"writing","title":"Writing","parts":2,"minutes":60},{"kind":"speaking","title":"Speaking","parts":3,"minutes":15,"approx":true}],"listening":[{"id":"l1","index":1,"instruction":"You will hear some sentences. Choose the correct reply to each sentence.","emphasis":"A, B or C","durationSec":48,"questions":[{"id":"l-1","number":1,"kind":"mcq","prompt":"","options":[{"key":"A","text":"Not yet, I'm nearly done."},{"key":"B","text":"I finished it tomorrow."},{"key":"C","text":"It's maths homework."}]},{"id":"l-2","number":2,"kind":"mcq","prompt":"","options":[{"key":"A","text":"Yes, I'm taking it."},{"key":"B","text":"Yes, please. Tell her Akmal called."},{"key":"C","text":"No, it's a long message."}]},{"id":"l-3","number":3,"kind":"mcq","prompt":"","options":[{"key":"A","text":"I like it."},{"key":"B","text":"It's Tuesday."},{"key":"C","text":"Sunny, but quite windy."}]},{"id":"l-4","number":4,"kind":"mcq","prompt":"","options":[{"key":"A","text":"You're welcome, any time."},{"key":"B","text":"Help yourself."},{"key":"C","text":"I'm fine, thanks."}]},{"id":"l-5","number":5,"kind":"mcq","prompt":"","options":[{"key":"A","text":"The metro is quicker at this time of day."},{"key":"B","text":"It's a new car."},{"key":"C","text":"I went by car."}]},{"id":"l-6","number":6,"kind":"mcq","prompt":"","options":[{"key":"A","text":"I don't need money."},{"key":"B","text":"Yes, just around the corner."},{"key":"C","text":"It opens at nine."}]},{"id":"l-7","number":7,"kind":"mcq","prompt":"","options":[{"key":"A","text":"That's a nice shirt."},{"key":"B","text":"I'll order two then."},{"key":"C","text":"Oh, when will you have it again?"}]},{"id":"l-8","number":8,"kind":"mcq","prompt":"","options":[{"key":"A","text":"No, not at all."},{"key":"B","text":"Yes, it's a few minutes."},{"key":"C","text":"I'll wait tomorrow."}]}],"audio":"t15/l1.mp3","audioAt":{"1":7,"2":11,"3":18,"4":22,"5":26,"6":31,"7":36,"8":41}},{"id":"l2","index":2,"title":"City Cooking School — beginners’ course","instruction":"You will hear a chef talking to new students. Fill in the missing information. Write","emphasis":"ONE WORD and / or A NUMBER","durationSec":75,"questions":[{"id":"l-9","number":9,"kind":"gap","prompt":"The course lasts … weeks"},{"id":"l-10","number":10,"kind":"gap","prompt":"Classes are on … mornings"},{"id":"l-11","number":11,"kind":"gap","prompt":"Every student must bring an"},{"id":"l-12","number":12,"kind":"gap","prompt":"The first dish: … soup"},{"id":"l-13","number":13,"kind":"gap","prompt":"Maximum … students in each class"},{"id":"l-14","number":14,"kind":"gap","prompt":"At the end, students receive a"}],"audio":"t15/l2.mp3","audioAt":{"9":20,"10":29,"11":42,"12":50,"13":57,"14":64}},{"id":"l3","index":3,"instruction":"You will hear people speaking in different situations. Match each speaker (15–18) to the place where the speaker is (A–F). There are","emphasis":"TWO EXTRA places","durationSec":64,"choices":[{"key":"A","text":"in a park"},{"key":"B","text":"at a wedding"},{"key":"C","text":"at a police station"},{"key":"D","text":"in a shoe shop"},{"key":"E","text":"in a library"},{"key":"F","text":"at an airport"}],"questions":[{"id":"l-15","number":15,"kind":"match","prompt":"Speaker 1"},{"id":"l-16","number":16,"kind":"match","prompt":"Speaker 2"},{"id":"l-17","number":17,"kind":"match","prompt":"Speaker 3"},{"id":"l-18","number":18,"kind":"match","prompt":"Speaker 4"}],"audio":"t15/l3.mp3","audioAt":{"15":14,"16":28,"17":38,"18":50}},{"id":"l4","index":4,"instruction":"You will hear someone giving a talk. Label the places (19–23) on the map (A–H). There are","emphasis":"THREE extra options","durationSec":57,"choices":[{"key":"A","text":""},{"key":"B","text":""},{"key":"C","text":""},{"key":"D","text":""},{"key":"E","text":""},{"key":"F","text":""},{"key":"G","text":""},{"key":"H","text":""}],"map":{"width":320,"height":240,"roads":[{"points":[[10,90],[310,90]]},{"points":[[200,90],[200,230]]},{"points":[[70,10],[70,90]]}],"blocks":[{"x":8,"y":30,"w":50,"h":32,"letter":"B"},{"x":84,"y":30,"w":52,"h":32,"letter":"A"},{"x":148,"y":48,"w":48,"h":30,"letter":"C"},{"x":245,"y":48,"w":55,"h":30,"letter":"D"},{"x":20,"y":104,"w":60,"h":32,"letter":"E"},{"x":120,"y":104,"w":60,"h":32,"letter":"F"},{"x":212,"y":104,"w":72,"h":32,"name":"Bus station"},{"x":215,"y":170,"w":60,"h":32,"letter":"G"},{"x":125,"y":180,"w":60,"h":32,"letter":"H"}],"labels":[{"x":40,"y":94,"text":"Sea Road"},{"x":70,"y":20,"text":"Hill Road"},{"x":200,"y":236,"text":"Pine Street"}]},"questions":[{"id":"l-19","number":19,"kind":"match","prompt":"Swimming pool"},{"id":"l-20","number":20,"kind":"match","prompt":"Bank"},{"id":"l-21","number":21,"kind":"match","prompt":"Souvenir shop"},{"id":"l-22","number":22,"kind":"match","prompt":"Hospital"},{"id":"l-23","number":23,"kind":"match","prompt":"Ferry office"}],"audio":"t15/l4.mp3","audioAt":{"19":20,"20":28,"21":34,"22":39,"23":47}},{"id":"l5","index":5,"instruction":"You will hear three extracts. Choose the correct answer (A, B or C) for each question. There are","emphasis":"TWO questions for each extract","durationSec":97,"questions":[{"id":"l-24","number":24,"kind":"mcq","prompt":"Why can’t Kamila go to the concert?","options":[{"key":"A","text":"She has an exam the next day."},{"key":"B","text":"The ticket is too expensive."},{"key":"C","text":"She is ill."}],"group":"Extract One"},{"id":"l-25","number":25,"kind":"mcq","prompt":"What will they do with Kamila’s ticket?","options":[{"key":"A","text":"sell it online"},{"key":"B","text":"give it to her brother"},{"key":"C","text":"keep it for another concert"}],"group":"Extract One"},{"id":"l-26","number":26,"kind":"mcq","prompt":"Why did Sanjar return to his village?","options":[{"key":"A","text":"His father became ill."},{"key":"B","text":"He could not find a job in the city."},{"key":"C","text":"He had always wanted to be a farmer."}],"group":"Extract Two"},{"id":"l-27","number":27,"kind":"mcq","prompt":"What has helped his business most?","options":[{"key":"A","text":"selling directly to customers online"},{"key":"B","text":"a loan from the government"},{"key":"C","text":"exporting to other countries"}],"group":"Extract Two"},{"id":"l-28","number":28,"kind":"mcq","prompt":"Why is the patient calling?","options":[{"key":"A","text":"to cancel her appointment"},{"key":"B","text":"to move her appointment"},{"key":"C","text":"to ask about the price"}],"group":"Extract Three"},{"id":"l-29","number":29,"kind":"mcq","prompt":"When is her new appointment?","options":[{"key":"A","text":"Monday at nine"},{"key":"B","text":"Tuesday at three"},{"key":"C","text":"Thursday at eleven"}],"group":"Extract Three"}],"audio":"t15/l5.mp3","audioAt":{"24":21,"25":31,"26":49,"27":59,"28":77,"29":86}},{"id":"l6","index":6,"title":"The history of chess","instruction":"You will hear a part of a lecture. Fill in the missing information. Write","emphasis":"no more than ONE WORD","durationSec":64,"questions":[{"id":"l-30","number":30,"kind":"gap","prompt":"Chess probably began in"},{"id":"l-31","number":31,"kind":"gap","prompt":"The early game was based on an"},{"id":"l-32","number":32,"kind":"gap","prompt":"From Persia, chess spread to the … world"},{"id":"l-33","number":33,"kind":"gap","prompt":"In Europe, the queen became the most … piece"},{"id":"l-34","number":34,"kind":"gap","prompt":"In 1997, a computer called Deep … beat the world champion"},{"id":"l-35","number":35,"kind":"gap","prompt":"Chess can improve concentration and"}],"audio":"t15/l6.mp3","audioAt":{"30":15,"31":22,"32":29,"33":37,"34":46,"35":54}}],"reading":[{"id":"r1","index":1,"title":"Keeping a diary","instruction":"Read the text. Fill in each gap with ONE word. You must use a word which is somewhere in the rest of the text.","passage":[{"label":"1","text":"Writing a diary is an old habit, but it is becoming popular again. Many (1) ______ say that writing for just ten minutes a day helps them feel calmer. A diary is a private place where you can describe your (2) ______ honestly, without worrying about what others think."},{"label":"2","text":"Some people write about their day; others list three things they are (3) ______ for. Experts say this simple exercise can improve your mood. Writing also helps you remember (4) ______ that might otherwise be forgotten. Years later, reading an old diary can be like meeting your younger (5) ______."},{"label":"3","text":"You do not need an expensive notebook; your (6) ______ is enough. Writers of diaries often say they feel calmer and more grateful, and many write on their phone before bed. Their old diaries keep important moments and feelings safe, and bring their younger self back to life."}],"questions":[{"id":"r-1","number":1,"kind":"gap","prompt":"Many (1) ______ say that writing helps them feel calmer."},{"id":"r-2","number":2,"kind":"gap","prompt":"You can describe your (2) ______ honestly."},{"id":"r-3","number":3,"kind":"gap","prompt":"Others list three things they are (3) ______ for."},{"id":"r-4","number":4,"kind":"gap","prompt":"Writing helps you remember (4) ______."},{"id":"r-5","number":5,"kind":"gap","prompt":"It can be like meeting your younger (5) ______."},{"id":"r-6","number":6,"kind":"gap","prompt":"Your (6) ______ is enough."}]},{"id":"r2","index":2,"title":"Sports clubs","instruction":"Read the texts 7–14 and the statements A–J. Decide which text matches the situation in each statement. Each statement can be used ONCE only. There are TWO extra statements.","passage":[{"label":"7","text":"PARK RUNNERS — Free group runs every Sunday morning. All levels welcome; just turn up and run."},{"label":"8","text":"ACE TENNIS — Private lessons with a former national champion. Book early, places are limited."},{"label":"9","text":"FAMILY SWIM — Every Saturday, parents and children can enjoy the pool together. Toys and floats provided."},{"label":"10","text":"KURASH CENTRE — Discover Uzbekistan’s national wrestling. Beginners’ classes for teenagers and adults."},{"label":"11","text":"VERTICAL CLIMBING WALL — Open every day until midnight. Climb after work or late in the evening."},{"label":"12","text":"WOMEN’S FOOTBALL — Our new women’s team is looking for players. Friendly matches every month."},{"label":"13","text":"MOUNTAIN CYCLING TOURS — Weekend rides into the mountains. Bikes and helmets are provided."},{"label":"14","text":"DESK YOGA — 30-minute classes at lunchtime, right next to the business centre. Come in your work clothes."}],"choices":[{"key":"A","text":"You can only exercise late at night."},{"key":"B","text":"You want lessons from a top player."},{"key":"C","text":"You need help preparing for a marathon."},{"key":"D","text":"You want an activity to do with your children."},{"key":"E","text":"You do not have your own equipment."},{"key":"F","text":"You want to try a traditional national sport."},{"key":"G","text":"You want to learn to ski."},{"key":"H","text":"You want to exercise during your lunch break."},{"key":"I","text":"You are a woman looking for a team to join."},{"key":"J","text":"You do not want to pay anything."}],"questions":[{"id":"r-7","number":7,"kind":"match","prompt":"Text 7"},{"id":"r-8","number":8,"kind":"match","prompt":"Text 8"},{"id":"r-9","number":9,"kind":"match","prompt":"Text 9"},{"id":"r-10","number":10,"kind":"match","prompt":"Text 10"},{"id":"r-11","number":11,"kind":"match","prompt":"Text 11"},{"id":"r-12","number":12,"kind":"match","prompt":"Text 12"},{"id":"r-13","number":13,"kind":"match","prompt":"Text 13"},{"id":"r-14","number":14,"kind":"match","prompt":"Text 14"}]},{"id":"r3","index":3,"title":"The true cost of fast fashion","instruction":"Read the text and choose the correct heading for each paragraph from the list of headings. There are more headings than paragraphs, so you will not use all of them.","passage":[{"label":"I","text":"Not long ago, clothes shops changed their collections twice a year, for summer and winter. Today, some big brands bring new designs into their shops every week. Prices are so low that a T-shirt can cost less than a sandwich."},{"label":"II","text":"But cheap clothes are expensive for the planet. Growing cotton uses huge amounts of water, and the dyes used to colour fabrics often end up in rivers. The fashion industry is also responsible for a large share of the world’s greenhouse gas emissions."},{"label":"III","text":"Behind every cheap shirt there are also workers, often young women in poorer countries, who work long hours for very low pay. In some factories, conditions are unsafe, and terrible accidents have made headlines around the world."},{"label":"IV","text":"Because clothes are so cheap, many people no longer look after them. Studies suggest that some items are worn only a few times before they are thrown away, and enormous amounts of clothing end up in rubbish dumps every year."},{"label":"V","text":"There are signs of change, especially among young people. Second-hand shops and apps for selling used clothes have become very popular, and wearing something old is now seen as stylish rather than embarrassing."},{"label":"VI","text":"Experts say the best thing shoppers can do is simple: buy fewer clothes, choose good quality and keep them for longer. Repairing a jacket or swapping clothes with friends can save money and help the environment at the same time."}],"choices":[{"key":"A","text":"The rise of second-hand"},{"key":"B","text":"A heavy price for nature"},{"key":"C","text":"Clothes at lightning speed"},{"key":"D","text":"The history of the shopping centre"},{"key":"E","text":"Buy less, choose well"},{"key":"F","text":"Worn once, then thrown away"},{"key":"G","text":"The people who make our clothes"},{"key":"H","text":"Designer brands for everyone"}],"questions":[{"id":"r-15","number":15,"kind":"match","prompt":"Paragraph I"},{"id":"r-16","number":16,"kind":"match","prompt":"Paragraph II"},{"id":"r-17","number":17,"kind":"match","prompt":"Paragraph III"},{"id":"r-18","number":18,"kind":"match","prompt":"Paragraph IV"},{"id":"r-19","number":19,"kind":"match","prompt":"Paragraph V"},{"id":"r-20","number":20,"kind":"match","prompt":"Paragraph VI"}]},{"id":"r4","index":4,"title":"My grandmother’s kitchen","instruction":"Read the text. For questions 21–24, choose the correct answer A, B, C or D. For questions 25–29, decide if the statements agree with the information in the text.","passage":[{"label":"1","text":"My grandmother has cooked for our family in Andijan for more than sixty years. She learned from her own mother, standing on a stool in a small kitchen, and she has never used a cookbook. When she turned eighty, I suddenly realised that none of her recipes had ever been written down. If we did not record them, they would be lost."},{"label":"2","text":"I thought it would be easy: I would ask her questions, and she would tell me the recipes. But when I asked how much flour to put in her famous pastries, she looked at me as if I had asked something very strange. “Enough,” she said. She had never measured anything in her life; she cooked by feel, by smell and by memory."},{"label":"3","text":"So we changed our method. Every Sunday I cooked with her, and before she added anything to the pot, I weighed it or poured it into a measuring cup. It drove her a little mad, but slowly a notebook filled with real quantities, times and temperatures."},{"label":"4","text":"It took almost a year to collect forty recipes, from everyday soups to the dishes she makes only for weddings. Every one of them comes from her own kitchen. My cousin, who is good at photography, took pictures, and last month we printed the book and gave a copy to every family in our large family."},{"label":"5","text":"At the family dinner where we gave it out, my grandmother turned the pages slowly. Then she said that the plov recipe was wrong — she always adds a little more cumin than I had written. We all laughed, and I made a note for the second edition."}],"questions":[{"id":"r-21","number":21,"kind":"mcq","prompt":"Why did the writer start recording the recipes?","options":[{"key":"A","text":"His grandmother asked him to."},{"key":"B","text":"The recipes had never been written down."},{"key":"C","text":"He wanted to open a restaurant."},{"key":"D","text":"He needed them for a cooking competition."}]},{"id":"r-22","number":22,"kind":"mcq","prompt":"What was the main difficulty at first?","options":[{"key":"A","text":"His grandmother did not want to share the recipes."},{"key":"B","text":"His grandmother never used exact amounts."},{"key":"C","text":"He did not have enough time."},{"key":"D","text":"Some ingredients were hard to find."}]},{"id":"r-23","number":23,"kind":"mcq","prompt":"How did the writer solve the problem?","options":[{"key":"A","text":"He found an old cookbook."},{"key":"B","text":"He asked other relatives."},{"key":"C","text":"He measured everything while she cooked."},{"key":"D","text":"He watched videos of other cooks."}]},{"id":"r-24","number":24,"kind":"mcq","prompt":"What happened to the finished book?","options":[{"key":"A","text":"It was sold in bookshops."},{"key":"B","text":"It won a prize."},{"key":"C","text":"Copies were given to the family."},{"key":"D","text":"It was published online."}]},{"id":"r-25","number":25,"kind":"tfng","prompt":"The grandmother learned to cook from her mother."},{"id":"r-26","number":26,"kind":"tfng","prompt":"The grandmother kept her recipes in a notebook."},{"id":"r-27","number":27,"kind":"tfng","prompt":"The writer works as a professional cook."},{"id":"r-28","number":28,"kind":"tfng","prompt":"Collecting the recipes took about a year."},{"id":"r-29","number":29,"kind":"tfng","prompt":"The book includes recipes from other countries."}]},{"id":"r5","index":5,"title":"The Tashkent metro","instruction":"Read the text. For questions 30–33, fill in the missing information. Write no more than ONE WORD and / or A NUMBER. For questions 34–35, choose the correct answer A, B, C or D.","passage":[{"label":"1","text":"The Tashkent metro opened in 1977 and was the first underground railway in Central Asia. It was built a decade after a powerful earthquake had destroyed much of the city, so engineers designed the tunnels and stations to survive earthquakes."},{"label":"2","text":"What makes the metro special is its decoration. Each station has its own theme, created with marble, granite, ceramics and chandeliers. Kosmonavtlar station, for example, is dedicated to space exploration, with portraits of famous cosmonauts on its walls."},{"label":"3","text":"For many years, visitors could only admire the stations from memory, because taking photographs underground was not allowed. The ban was finally lifted in 2018, and since then the stations have become popular on social media."},{"label":"4","text":"Today the metro is still growing, with new lines carrying commuters to the city’s newer districts. For local people it is a cheap and fast way to travel, and for tourists it is one of the city’s most surprising attractions: a museum that you can visit for the price of a ticket."}],"questions":[{"id":"r-30","number":30,"kind":"gap","prompt":"The Tashkent metro opened in"},{"id":"r-31","number":31,"kind":"gap","prompt":"The stations were designed to survive"},{"id":"r-32","number":32,"kind":"gap","prompt":"Kosmonavtlar station is dedicated to … exploration."},{"id":"r-33","number":33,"kind":"gap","prompt":"Until 2018, taking … underground was not allowed."},{"id":"r-34","number":34,"kind":"mcq","prompt":"Why do tourists enjoy visiting the metro?","options":[{"key":"A","text":"It is the fastest metro in the world."},{"key":"B","text":"Its stations are beautifully decorated."},{"key":"C","text":"Tickets for tourists are free."},{"key":"D","text":"It has a museum about trains."}]},{"id":"r-35","number":35,"kind":"mcq","prompt":"What is the writer’s main purpose?","options":[{"key":"A","text":"to describe the history and special features of the metro"},{"key":"B","text":"to complain about public transport in Tashkent"},{"key":"C","text":"to compare the metro with buses"},{"key":"D","text":"to explain how earthquakes happen"}]}]}],"writing":[{"id":"w1","index":1,"label":"Task 1","kind":"Letter","context":"You have read an article in an English-language magazine which says that young people today do not read books.","prompt":"Write an email to the editor of the magazine. In your email:\n- say whether you agree with the article;\n- describe your own reading habits;\n- suggest how young people could be encouraged to read more.\nWrite about 150 words in an appropriate format and style.","targetWords":150,"minWords":120,"weight":1},{"id":"w2","index":2,"label":"Task 2","kind":"Essay","prompt":"Some people believe that famous sports stars earn far too much money. Others think they deserve their high salaries.\n\nDiscuss both views and give your opinion. Write at least 250 words in an appropriate style and format.","targetWords":250,"minWords":250,"weight":2}],"speaking":[{"id":"s1","index":1,"part":"1.1","prompt":"What is your favourite season, and why?","prepSec":5,"answerSec":30},{"id":"s2","index":2,"part":"1.1","prompt":"How often do you use the internet, and what for?","prepSec":5,"answerSec":30},{"id":"s3","index":3,"part":"1.1","prompt":"Tell me about your best friend.","prepSec":5,"answerSec":30},{"id":"s4","index":4,"part":"1.2","prompt":"Compare the two pictures. What are the similarities and differences?","image":"Picture A: people shopping online at home · Picture B: people shopping in a busy shopping centre","prepSec":10,"answerSec":45},{"id":"s5","index":5,"part":"1.2","prompt":"Which way of shopping do you prefer? Why?","image":"Picture A: people shopping online at home · Picture B: people shopping in a busy shopping centre","prepSec":5,"answerSec":30},{"id":"s6","index":6,"part":"1.2","prompt":"What are the risks of shopping online?","image":"Picture A: people shopping online at home · Picture B: people shopping in a busy shopping centre","prepSec":5,"answerSec":30},{"id":"s7","index":7,"part":"2","prompt":"Describe a teacher who has had a strong influence on you. Say who they were, what they taught you and why they were special.","image":"A woman teaching a small group of adults in a community centre","prepSec":60,"answerSec":120},{"id":"s8","index":8,"part":"3","prompt":"Everyone should do sport every day. For: sport keeps people healthy and reduces stress. Against: people have different interests and not enough time. Give arguments for and against this statement and say what you think.","prepSec":60,"answerSec":120}]}$json$::jsonb)
