insert into public.test_keys (test_id, keys, scripts)
values ('t15', $json${"l-1":{"answer":"A"},"l-2":{"answer":"B"},"l-3":{"answer":"C"},"l-4":{"answer":"A"},"l-5":{"answer":"A"},"l-6":{"answer":"B"},"l-7":{"answer":"C","explanation":"\"Out of stock\" — omborda yo'q, shuning uchun qachon bo'lishini so'rash mantiqiy."},"l-8":{"answer":"A"},"l-9":{"answer":"6|six"},"l-10":{"answer":"Saturday","explanation":"Avval yakshanba edi, hozir shanba."},"l-11":{"answer":"apron"},"l-12":{"answer":"lentil"},"l-13":{"answer":"12|twelve"},"l-14":{"answer":"certificate"},"l-15":{"answer":"B"},"l-16":{"answer":"D"},"l-17":{"answer":"C","explanation":"Aeroport tilga olinadi — sumka u yerda o'g'irlangan, lekin gapirayotgan joy — politsiya bo'limi."},"l-18":{"answer":"A"},"l-19":{"answer":"A"},"l-20":{"answer":"D","explanation":"\"Directly opposite the bus station\" — avtovokzal qarshisida, shimoliy tomonda."},"l-21":{"answer":"F"},"l-22":{"answer":"H"},"l-23":{"answer":"E"},"l-24":{"answer":"A"},"l-25":{"answer":"B"},"l-26":{"answer":"A"},"l-27":{"answer":"A","explanation":"Kredit olmaganini aytadi; eksport — kelajak rejasi."},"l-28":{"answer":"B"},"l-29":{"answer":"B"},"l-30":{"answer":"India"},"l-31":{"answer":"army"},"l-32":{"answer":"Arab|Islamic|Muslim"},"l-33":{"answer":"powerful"},"l-34":{"answer":"Blue"},"l-35":{"answer":"memory"},"r-1":{"answer":"writers"},"r-2":{"answer":"feelings"},"r-3":{"answer":"grateful"},"r-4":{"answer":"moments"},"r-5":{"answer":"self"},"r-6":{"answer":"phone"},"r-7":{"answer":"J","explanation":"Marafonga tayyorlov (C) haqida gap yo'q — faqat bepul yugurish."},"r-8":{"answer":"B"},"r-9":{"answer":"D"},"r-10":{"answer":"F"},"r-11":{"answer":"A"},"r-12":{"answer":"I"},"r-13":{"answer":"E"},"r-14":{"answer":"H"},"r-15":{"answer":"C"},"r-16":{"answer":"B"},"r-17":{"answer":"G"},"r-18":{"answer":"F"},"r-19":{"answer":"A"},"r-20":{"answer":"E"},"r-21":{"answer":"B"},"r-22":{"answer":"B"},"r-23":{"answer":"C"},"r-24":{"answer":"C"},"r-25":{"answer":"True"},"r-26":{"answer":"False"},"r-27":{"answer":"No Information"},"r-28":{"answer":"True"},"r-29":{"answer":"False","explanation":"Har bir retsept buvisining oshxonasidan — chet el retseptlari yo'q."},"r-30":{"answer":"1977"},"r-31":{"answer":"earthquakes"},"r-32":{"answer":"space"},"r-33":{"answer":"photographs|photos|pictures"},"r-34":{"answer":"B"},"r-35":{"answer":"A"}}$json$::jsonb, $json$[{"partId":"l1","lines":[{"voice":"narrator","text":"Part one. You will hear some sentences. Choose the correct reply to each sentence."},{"voice":"woman","text":"Have you finished your homework yet?","question":1},{"voice":"man","text":"I'm sorry, Nilufar isn't here at the moment. Can I take a message?","question":2},{"voice":"woman","text":"What's the weather like today?","question":3},{"voice":"man","text":"Thank you so much for your help!","question":4},{"voice":"woman","text":"Shall we go by car or by metro?","question":5},{"voice":"man","text":"Excuse me, is there a bank near here?","question":6},{"voice":"woman","text":"I'm afraid the shirt you ordered is out of stock.","question":7},{"voice":"man","text":"Do you mind waiting for a few minutes?","question":8},{"voice":"narrator","text":"That is the end of part one."}]},{"partId":"l2","lines":[{"voice":"narrator","text":"Part two. You will hear a chef talking to new students. Fill in the missing information. Write one word and, or, a number for each answer."},{"voice":"man","text":"Welcome to the City Cooking School. I'm chef Bahrom, and I'll be teaching you on the beginners' course."},{"voice":"man","text":"The course lasts six weeks, and in that time you'll learn twelve dishes, from simple salads to a proper plov.","question":9},{"voice":"man","text":"Classes used to be on Sunday mornings, but many students asked us to change, so now all classes are on Saturday mornings, from ten until one.","question":10},{"voice":"man","text":"We provide all the ingredients and knives, but every student must bring an apron. Your clothes will thank you!","question":11},{"voice":"man","text":"We'll start with something simple and healthy: lentil soup. Next week we'll move on to fresh bread.","question":12},{"voice":"man","text":"To make sure everyone gets enough attention, there's a maximum of twelve students in each class.","question":13},{"voice":"man","text":"And at the end of the course, after a final cooking test, every student receives a certificate.","question":14},{"voice":"narrator","text":"That is the end of part two."}]},{"partId":"l3","lines":[{"voice":"narrator","text":"Part three. You will hear people speaking in different situations. Match each speaker to the place where the speaker is. There are two extra places which you do not need to use."},{"voice":"narrator","text":"Speaker 1.","question":15},{"voice":"man","text":"Ladies and gentlemen, please raise your glasses to the bride and groom. I've known Aziz since we were five, and I've never seen him as happy as he is today."},{"voice":"narrator","text":"Speaker 2.","question":16},{"voice":"woman","text":"These are a bit tight at the front. Could I try them in a size forty-two? And do you have the same style in brown, maybe without laces?"},{"voice":"narrator","text":"Speaker 3.","question":17},{"voice":"man2","text":"I'd like to report a stolen bag. It was taken at the airport this morning, while I was buying coffee. Yes, I can fill in the form now. My passport was inside."},{"voice":"narrator","text":"Speaker 4.","question":18},{"voice":"woman2","text":"Look, there's a free bench by the fountain. Let's sit in the shade for a while. And please put the dog back on the lead, the sign says so."},{"voice":"narrator","text":"That is the end of part three."}]},{"partId":"l4","lines":[{"voice":"narrator","text":"Part four. You will hear someone giving a talk. Label the places on the map. There are three extra options which you do not need to use."},{"voice":"woman","text":"Welcome to Seaside Town. We're at the bus station, on the south side of Sea Road, just east of Pine Street. Here are a few places you might need."},{"voice":"woman","text":"For the swimming pool, walk west along Sea Road and turn right into Hill Road. Walk north, and the pool is on your right.","question":19},{"voice":"woman","text":"If you need money, the bank is directly opposite the bus station, on the north side of Sea Road.","question":20},{"voice":"woman","text":"The souvenir shop is on the corner of Sea Road and Pine Street, on the west side of Pine Street.","question":21},{"voice":"woman","text":"The hospital is down Pine Street. Walk south, and it's near the end of the street, on your right.","question":22},{"voice":"woman","text":"And to take the ferry to the island, go to the ferry office at the western end of Sea Road, on the south side.","question":23},{"voice":"narrator","text":"That is the end of part four."}]},{"partId":"l5","lines":[{"voice":"narrator","text":"Part five. You will hear three extracts. Choose the correct answer for each question. There are two questions for each extract."},{"voice":"narrator","text":"Extract one. You will hear two friends talking about a concert."},{"voice":"man","text":"Kamila, the concert is on Friday! Are you ready?"},{"voice":"woman","text":"I'm so sorry, I can't come after all. I'm not ill and I've already paid for the ticket, but I've just found out my exam is on Saturday morning, so I need to study.","question":24},{"voice":"woman","text":"I don't want to sell it online, it's too complicated. My brother loves this band, so I'll give it to him. You two can go together.","question":25},{"voice":"narrator","text":"Extract two. You will hear part of a radio interview with a young farmer."},{"voice":"woman2","text":"Sanjar, you left a job in Tashkent to grow strawberries in your village. Why?"},{"voice":"man2","text":"I liked my job in the city, and I never planned to be a farmer. But my father became seriously ill, and someone had to look after the greenhouses, so I went home.","question":26},{"voice":"man2","text":"I didn't get any loans. What changed everything was selling directly to customers online. People order in the morning, and the strawberries arrive the same day. Exporting is our plan for the future.","question":27},{"voice":"narrator","text":"Extract three. You will hear a phone call to a dentist's surgery."},{"voice":"woman3","text":"Hello, I have an appointment on Monday at nine, but I have to travel for work. I don't want to cancel; can I move it to later in the week?","question":28},{"voice":"man3","text":"Let me see. Thursday at eleven is taken, I'm afraid, but there's a free slot on Tuesday at three. Shall I book that for you?","question":29},{"voice":"narrator","text":"That is the end of part five."}]},{"partId":"l6","lines":[{"voice":"narrator","text":"Part six. You will hear a part of a lecture. Fill in the missing information. Write no more than one word for each answer."},{"voice":"man3","text":"Good afternoon. Today we're looking at the long history of one of the world's oldest games: chess."},{"voice":"man3","text":"Most historians believe that chess began in India about fifteen hundred years ago, with a game called chaturanga.","question":30},{"voice":"man3","text":"The early game was based on an army, with pieces representing foot soldiers, horses, chariots and elephants.","question":31},{"voice":"man3","text":"From India the game travelled to Persia, and from there it spread across the Arab world, where many of its rules were written down.","question":32},{"voice":"man3","text":"When chess reached Europe, some pieces changed. In the fifteenth century, the queen became the most powerful piece on the board, which made the game much faster.","question":33},{"voice":"man3","text":"In 1997, chess made headlines again, when a computer called Deep Blue defeated the world champion, Garry Kasparov.","question":34},{"voice":"man3","text":"Today, many schools teach chess, because studies suggest it can improve concentration and memory.","question":35},{"voice":"narrator","text":"That is the end of part six."}]}]$json$::jsonb)
on conflict (test_id) do update set keys = excluded.keys, scripts = excluded.scripts;
